    'cli.doctor.php' => '{version} em {binary}',
    'cli.doctor.php_too_old' => '{version} em {binary} (candy-code requer PHP 8.3+)',
    'cli.doctor.provider' => '{provider} (modelo {model})',
    'cli.doctor.provider_none' => 'nenhum selecionado — o backend de eco offline responderá (defina CANDY_CODE_PROVIDER)',
    'cli.doctor.provider_shell' => 'backend de execução externa (nível $CANDY_CODE_BACKEND_CMD)',
    'cli.doctor.provider_unconstructable' => '{provider} está selecionado mas não pode ser construído: {error}',
    'cli.doctor.provider_unknown' => '{provider} está selecionado mas não é um fornecedor conhecido — veja `candy-code models`',
    'cli.doctor.sandbox_binary' => '{backend} em {path}',
    'cli.doctor.sandbox_binary_absent' => '{backend} não encontrado no PATH',
    'cli.doctor.sandbox_nonlinux' => 'bashSandbox "{mode}" está configurado mas o bubblewrap é exclusivo para Linux e este host é {os}',
    'cli.doctor.sandbox_nonlinux_off' => 'bashSandbox está desativado; o bubblewrap é exclusivo para Linux e este host é {os}',
