    'cli.doctor.sandbox_refused' => 'bashSandbox "{mode}" está configurado mas a jail não inicia ({reason}) — {remedy}',
    'cli.doctor.sandbox_remedy_apparmor' => 'instalar o bubblewrap, ou adicionar um perfil em /etc/apparmor.d que conceda ao bwrap namespaces de utilizador sem privilégios (o sysctl apparmor_restrict_unprivileged_userns é a alternativa grosseira)',
    'cli.doctor.sandbox_remedy_generic' => 'instalar o bubblewrap, ou definir bashSandbox como "off"',
    'cli.doctor.sandbox_remedy_seatbelt' => 'verificar que /usr/bin/sandbox-exec ainda funciona nesta instalação macOS, ou definir bashSandbox como "off"',
    'cli.doctor.server_ready' => 'pcntl, posix e ffi disponíveis — `serve` pode iniciar',
    'cli.doctor.server_refuses' => '`serve` recusará iniciar: {problems}',
    'cli.doctor.sessions' => '{count} sessão(ões) armazenada(s)',
    'cli.doctor.settings_clean' => 'todos os ficheiros de configuração contêm apenas chaves que o candy-code lê',
    'cli.doctor.unknown' => 'desconhecido',
    'cli.headless.permission_hint' => '  dica: uma execução `-p` sem modo nomeado inicia no modo `default` de pergunta; perguntas sem supervisão não têm ninguém para responder, pelo que falham em modo fechado. Execuções em script podem nomear --permission-mode bypass-permissions (ou accept-edits) para continuar.',
    'cli.help.screen' => <<<'TXT'
CandyCode — assistente de programação com IA para o terminal.

Utilização:
  candy-code                       Iniciar o TUI interativo (predefinição)
  candy-code <dir>                 Iniciar o TUI com raiz em <dir>, que deve
                                   existir (apenas como primeiro argumento)
  candy-code [<dir>] <words…>      Iniciar o TUI e enviar as palavras como
                                   primeiro prompt, ex.: candy-code fix the bug
  candy-code -c                    Continuar a sessão mais recente
  candy-code --resume [<id>]       Retomar uma sessão armazenada (seletor se sem id)
  candy-code -p <prompt>           Executar um único prompt e sair (one-shot)
  candy-code run "<prompt>"        Alias para -p "<prompt>" (modo one-shot)
  candy-code --output-format json  Saída JSON legível por máquina (one-shot)
  candy-code --worktree [<name>]   Executar esta sessão num git worktree
                                   próprio (criado se não existir)

Subcomandos (nenhum abre o TUI nem precisa de um fornecedor, uma chave de API ou
um terminal; cada um responde e sai, exceto serve e mcp serve, que correm até
serem parados — e attach, que é a exceção a ambos: executa o TUI numa sessão
de um servidor em execução; acp executa turnos para um editor, até este se desligar):
  bundles list           Listar os bundles de plugins que este diretório vê: nome,
                         versão, nível e as superfícies que cada um traz —
                         incluindo os hooks e .mcp.json que o candy-code
                         recusa executar.
  bundles install <src>  Copiar um diretório de bundle, ou clonar um URL git com
                         um clone de profundidade limitada a um, para a raiz de
                         bundles do utilizador (~/.candy-code/bundles), onde só você o possui.
  doctor                 Verificar esta instalação e reportar todos os problemas
                         encontrados: versão PHP, as extensões que o repositório
                         de sessões e serve precisam, o ficheiro de configuração, a
                         política de permissões, o fornecedor selecionado, a base
                         de dados de sessões e a configuração MCP do projeto. Sai
                         com 1 se alguma verificação FALHAR.
                         Distinto da ferramenta "doctor" invocável pelo modelo, que
                         reporta ao modelo o protocolo de imagens do terminal.
  import claude          Pré-visualizar importação das definições do Claude Code: lê o ficheiro de
                         definições do utilizador, mais o ficheiro de definições .claude sob a raiz de
                         arranque quando --project é indicado, traduz as suas listas de permissões
                         permitir/negar/perguntar para permissionRules (o lado mais restritivo
                         vence sempre — negar sobrepõe-se a permitir), mapeia o modelo e lista cada
                         chave sem destino como ignorada. Nada é escrito até ser
                         confirmado: --yes aceita a pré-visualização impressa diretamente, e
                         sem ele é solicitado um terminal interativo. A pré-visualização lista
                         cada regra de permitir que alargaria o que corre sem perguntar.
  login <provider>       Iniciar sessão num fornecedor: claude-code e codex passam o
                         terminal para a sua própria CLI (o token nunca passa
                         pelo candy-code); openai, anthropic e gemini
                         colam uma chave no bloco de fornecedores do ficheiro de configuração;
                         os restantes indicam quem realmente detém a sua credencial.
  models                 Listar os fornecedores que esta instalação pode selecionar e o
                         modelo predefinido de cada um; "*" marca o
                         selecionado.
  session list [--all|--archived|--children] [--limit N]
                         Listar sessões guardadas, fixadas primeiro, depois as mais recentes
                         primeiro: id, última atualização, tipo, turnos, fornecedor/modelo
                         e nome (★ marca uma linha fixada). --children adiciona
                         linhas de sub-agente e segundo plano, --archived adiciona
                         as arquivadas, --all adiciona ambas; 20 linhas a menos que
                         --limit indique o contrário.
  session show <target>  Imprimir detalhes e transcrição de uma sessão.
  session import <path> [--format auto|…] [--name <title>] [--force]
                         Importa um arquivo de transcrição como nova sessão:
                         uma exportação candy-code ou o histórico de
                         claude-code, codex ou opencode (--format nomeia, auto deduz).
  session rename <target> <title…>
                         Renomear uma sessão; as palavras após o destino são
                         o título.
  session delete <target> [--with-children]
                         Eliminar uma sessão. Os filhos de sub-agente vão com ela;
                         as ramificações são mantidas a menos que --with-children.
  session pin|unpin|archive|unarchive <target>
                         Fixar uma sessão (listada primeiro, nunca eliminada), ou
                         arquivá-la (oculta da lista predefinida, mantida).
                         <target> é um id, um nome ou um prefixo de id único.
                         Termina com 1 se nada corresponder, 2 se um prefixo for
                         ambíguo (os candidatos são listados).
  mcp list               Listar os servidores MCP declarados em .mcp.json, SEM
                         iniciar nenhum deles. Reporta antes quando o ficheiro
                         está ausente, resolve fora da árvore do projeto, ou está
                         presente mas a raiz do projeto não é confiável.
  mcp auth login <server> [token-url] [authorize-url] [registration-url]
                         Autentica um servidor MCP declarado com OAuth: abre
                         (ou imprime) o URL de autorização, capta o redire-
                         cionamento de loopback e guarda os tokens para depois.
  mcp trust              Aprovar o .mcp.json deste projeto como está: adicionar
                         a raiz a "trustedProjectMcp" e registar o comando, os
                         argumentos e o env de cada servidor, para que uma alteração posterior
                         a qualquer deles seja recusada no arranque até ser reaprovada.
                         Não inicia nada.
  mcp import claude|opencode|claude-project <path> [--write user]
                         Traduzir uma configuração MCP externa e imprimir o
                         bloco .mcp.json equivalente para stdout. Apenas imprime
                         por omissão; --write user acrescenta as entradas
                         traduzidas ao ~/.candy-code/mcp.json do utilizador
                         (uma colisão de nomes recusa toda a escrita, e o
                         nível de projeto nunca é escrito). As renomeações feitas
                         pela tradução são listadas em stderr.
  mcp serve [--root PATH]
                         Servir o candy-code como servidor MCP sobre stdio:
                         um quadro JSON-RPC por linha de entrada, uma resposta por linha
                         de saída, até o stdin fechar. As chamadas de ferramentas executam a lista
                         só de leitura (Read, Glob, Grep, Ls, RepoMap), restrita à
                         raiz do espaço de trabalho, através do PermissionGate do arranque
                         e da cadeia de hooks PreToolUse — este é o servidor
                         MCP que um cliente pode iniciar; o WebSocket
                         `candy-code serve` ainda não fala MCP. Corre até
                         ser parado.
  lsp install <language> Instalar o servidor de linguagem fixado para uma
                         linguagem: o pacote npm ou o binário de lançamento
                         verificado por checksum, na raiz de instalação privada sob
                         a sua pasta pessoal. `lsp list` indica quais as linguagens
                         instaláveis.
  lsp list               Reportar cada linguagem instalável: a sua versão
                         fixada, onde o seu servidor está instalado (ou que não
                         está), e se existe um lançamento para o SO e a
                         arquitetura desta máquina. Não inicia nada,
                         não descarrega nada.
  self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]
                         Substituir esta instalação phar pelo lançamento
                         candy-code mais recente publicado, verificado por sha256 contra o
                         sidecar de lançamento ANTES da substituição; o phar em execução é
                         mantido como <phar>.old e --rollback restaura exatamente
                         essa cópia uma vez. Quando uma chave pública de assinatura está fixada
                         na fonte de lançamento, a assinatura candy-code.phar.minisig
                         também deve ser verificada (--allow-unsigned ignora
                         apenas essa verificação). --check reporta apenas a atual vs
                         a mais recente e termina com 1 quando há atualização disponível. Uma
                         instalação via Composer é recusada com aviso, indicando o
                         comando composer update a executar em alternativa. Uma
                         instalação de desenvolvimento segue o lançamento contínuo candy-code/dev
                         por omissão (está atual quando o commit de destino do lançamento
                         corresponde ao sha do carimbo) e --channel
                         seleciona explicitamente um dos ramos.
  serve [--host <ip>] [--port <n>] [--allow-remote] [--allowed-host <list>]
        [--allowed-ips <list>] [--allowed-origin <list>] [--allow-dir-browse]
        [--browse-root <dir>] [--web-root <dir>] [--no-web] [--allow-bypass]
        [--allow-root] [--detach] [--parent-pid <pid>]
        [--tls-cert <file>] [--tls-key <file>]
                         Executa o servidor WebSocket + HTTP com que a UI web
                         comunica, em primeiro plano até Ctrl+C. Liga-se a 127.0.0.1:7420
                         por omissão e imprime um URL de início de sessão cujo código
                         de utilização única é trocado por um cookie do navegador; cada cliente
                         precisa dele ou do token em ~/.candy-code/server/token,
                         incluindo loopback. Opções:
      --host <ip>        Endereço a que se liga (127.0.0.1 por omissão; localhost e ::1
                         contam igualmente como loopback). Qualquer outro endereço é recusado
                         a menos que --allow-remote seja também fornecido.
      --port <n>         Porta a que se liga (7420 por omissão; 0 escolhe uma livre).
      --allow-remote     Permite um --host não-loopback. Sem --tls-cert e
                         --tls-key isto é HTTP simples: coloque um proxy reverso TLS
                         à frente, ou sirva TLS diretamente (ver abaixo). Em
                         0.0.0.0 ou :: o servidor responde aos próprios endereços
                         desta máquina, e o URL de início de sessão nomeia-os.
      --tls-cert <file>  Certificado PEM com que o próprio listener serve TLS,
                         fornecido em conjunto com --tls-key. O URL de início de sessão
                         passa a ler https://, o cookie de sessão transporta Secure,
                         e um cliente http:// em texto simples não recebe resposta alguma.
      --tls-key <file>   Chave privada PEM para --tls-cert: um ficheiro legível sem
                         bits de grupo ou de mundo expostos, correspondente ao certificado.
                         Um par inválido ou incompleto é recusado no arranque.
      --allowed-host <list>
                         Nomes de host adicionais (ou host:port) separados por vírgulas
                         a que o servidor responde, p. ex. um nome DNS desta máquina.
                         Repetível.
      --allowed-ips <list>
                         IPs de cliente ou intervalos CIDR (p. ex.
                         1.2.3.4,10.0.0.0/8) separados por vírgulas autorizados a ligar-se; qualquer outro
                         endereço é recusado com 403 antes do início de sessão. Loopback é
                         sempre permitido. Não definido: sem filtro de endereços.
                         Repetível.
      --allowed-origin <list>
                         Origens de navegador adicionais
                         (http(s)://host[:port]) separadas por vírgulas, autorizadas além da
                         própria do servidor. Repetível.
      --allow-dir-browse Permite a clientes autenticados escolher o diretório onde uma nova sessão
                         arranca: podem listar nomes de diretórios (nunca
                         ficheiros) sob --browse-root. Desativado por omissão.
      --browse-root <dir>
                         O diretório a que --allow-dir-browse está confinado
                         (por omissão, o seu diretório pessoal).
      --web-root <dir>   Serve a UI web a partir de <dir> em vez do pacote
                         sugarcraft/candy-code-web instalado.
      --no-web           Serve apenas a API e o WebSocket, sem ficheiros de UI.
      --allow-bypass     Permite que sessões corram em bypass-permissions ou dont-ask
                         (recusado por omissão; as sessões do servidor arrancam em
                         default a menos que --permission-mode diga o contrário).
      --allow-root       Permite executar como root (recusado por omissão).
      --detach           Executa em segundo plano: imprime o URL e o pid uma vez
                         a porta estar ligada, e sai; o servidor regista em
                         server.log no seu diretório de estado.
      --parent-pid <pid> Para o servidor quando o processo <pid> termina (para um
                         editor ou TUI que inicia um servidor privado).
                         Recusa-se a iniciar sem ext-pcntl, ext-posix e
                         ext-ffi (ver doctor). Sai com 1 se a porta estiver ocupada ou
                         se já correr um servidor do mesmo diretório de estado.
  serve status           Informa sobre o servidor em execução: pid, URL, root, tempo ativo e
                         se GET /api/health responde. Sai com 1 quando nenhum
                         está a correr.
  serve stop [--force]   Para-o: SIGTERM, até 30 s para esvaziar, depois SIGKILL.
      --force            SIGKILL de imediato.
  serve logs [-f]        Imprime o final do registo de um servidor em segundo plano.
  -f, --follow           Continua a imprimir o que é acrescentado até parar.
  serve url [--qr]       Imprime um URL de início de sessão com um código de utilização única novo.
      --qr              Renderiza cada URL de início de sessão como um código QR terminal escaneável.
  serve token [--rotate] Imprime o token de proprietário que os clientes bearer enviam.
      --rotate           Substitui-o; um servidor em execução mantém o antigo até
                         reiniciar.
  attach [<session>] [--url <url>]
                         Executa a TUI numa sessão de um candy-code
                         serve em execução: o servidor executa cada turno e as suas ferramentas, e
                         este terminal mostra-as e responde às perguntas de permissão
                         que estas levantam. <session> é um id, um nome ou um
                         prefixo de id único de uma das sessões do servidor;
                         sem ele, é criada uma nova. O servidor é o
                         que serve status reporta, o seu token obtido de
                         CANDY_CODE_SERVER_TOKEN ou do ficheiro de token
                         do diretório de estado. Sair desliga; um turno em execução
                         prossegue. Sai com 1 se nenhum servidor responder.
      --url <url>        Liga-se ao servidor em <url> (o endereço que serve
                         imprime) em alternativa.
  acp                    Executa como agente do Agent Client Protocol: o editor
                         (Zed, JetBrains, Neovim) inicia-o e comunica
                         JSON-RPC no seu stdin e stdout. As sessões abrem em
                         raiz do projeto do editor, os turnos executam-se aqui com este
                         fornecedor e ferramentas da instalação, e o editor responde
                         às suas perguntas de permissão. Não para terminal: stdout
                         transporta apenas o protocolo (todo o resto vai para
                         stderr). Termina com 0 quando o editor fecha stdin.
  completion bash|zsh|fish
                         Escreve um script de conclusão de shell em stdout, p. ex.
                         eval "$(candy-code completion bash)".
  usage [7|30|all] [--session <target>]
                         Agrega o livro de despesas persistente por dia e modelo:
                         a mesma página que `/usage` imprime, sobre a mesma
                         agregação partilhada. 7 e 30 tomam dias UTC completos,
                         incluindo hoje; all (ou sem operando) abrange todo o
                         livro-razão, e uma janela fora desse conjunto é
                         recusada em vez de alargada silenciosamente. --session
                         restringe a uma sessão por id, nome ou prefixo único;
                         --output-format json emite o mapa de factos de que a
                         página foi construída. Um livro-razão ilegível indica
                         o motivo e termina com 1; os dólares de agregações
                         com modelo sem preço: ≥ limite inferior, nunca soma simples.

Opções:
  -p, --prompt <text>    Fornece um prompt na linha de comandos (modo de execução única)
      --output-format <format>
                         Formato de saída: "text" (predefinição), "json" ou
                         "stream-json" (eventos NDJSON, resposta no fim)
      --root <dir>       Usa <dir> como raiz do projeto em vez do diretório
                         atual. Aceita também --root=<dir> (a forma a usar
                         quando <dir> começa por "-"); não pode ser omitido.
                         Nomear uma raiz aqui E como argumento posicional é
                         recusado em vez de uma ganhar silenciosamente.
      --config <file>    Lê definições, permissões e raízes de hooks confiáveis de
                         <file> em vez de ~/.candy-code/config.json. Aceita
                         também --config=<file>. Deve já existir, ser
                         legível, pertencer-lhe, e nem ele nem o seu
                         diretório podem ser graváveis por todos — transporta a
                         política de permissões, pelo que é sujeito ao mesmo
                         padrão de ~/.candy-code/config.json (um ficheiro em /etc
                         ou /tmp é normalmente recusado por um desses motivos).
                         Só o FICHEIRO muda: agentes, skills, fluxos de trabalho,
                         sessões e memória ficam em ~/.candy-code.
      --model <name>     Usa <name> como modelo de conversa, substituindo
                         $CANDY_CODE_MODEL e a predefinição do fornecedor. Aceita
                         também --model=<name>. Seleciona um modelo, não um
                         fornecedor — o fornecedor vem de $CANDY_CODE_PROVIDER ou
                         da definição `provider` persistida, e os dois são
                         eixos independentes.
      --permission-mode <mode>
                         Executa com <mode> em vez do modo no ficheiro de
                         configuração. Aceita também --permission-mode=<mode>.
                         Precedência máxima: sobrepõe-se a $CANDY_CODE_PERMISSION_MODE
                         e à chave permissionMode da configuração. Um de: default,
                         accept-edits, plan, auto, dont-ask,
                         bypass-permissions. Sem nenhum definido, o TUI e -p
                         iniciam em default (pergunta antes de escritas e comandos
                         de shell); só um daemon iniciado localmente começa em
                         bypass-permissions.
      --max-cost <usd>   Limita esta execução a <usd> dólares US de despesas
                         reportadas: o turno que ultrapassaria o teto é
                         recusado e não enviado. Aceita também --max-cost=<usd>.
                         Precedência máxima: sobrepõe-se a $CANDY_CODE_MAX_COST e
                         à chave maxCostUsd da configuração. Fracionário permitido,
                         $ inicial aceite ($2.50); zero e negativos são
                         recusados em vez de lidos como "sem limite". /budget
                         continua a aumentar ou limpar o limite da sessão ativa.
      --max-turns <n>    Limita esta execução a <n> passos do ciclo de ferramentas:
                         o turno que os esgota para onde está e diz-no.
                         Aceita também --max-turns=<n>. Precedência máxima:
                         sobrepõe-se à chave maxToolSteps (este eixo
                         não tem variável de ambiente). Um número inteiro
                         positivo; zero é recusado em vez de lido como "sem
                         limite", e um valor inutilizável recusa a execução
                         em vez de ceder silenciosamente à definição.
      --json-schema <path-or-json>
                         Restringe a resposta a um JSON Schema: um documento
                         {"type":"object",...} em linha ou um caminho para um
                         ficheiro que o contenha. Aceita também --json-schema=<value>;
                         a forma = é a a usar quando o caminho começa
                         por "-". Só fornecedores que reportam suporte a
                         respostas com restrição de esquema executam o pedido
                         — qualquer outro recusa com exit 2 em vez de
                         faturar por uma resposta sem restrição. O esquema
                         condiciona o pedido de auto-conclusão do turno; os passos
                         que continuam um ciclo de ferramentas ficam livres (uma
                         resposta JSON forçada não pode conter chamadas de ferramentas).
      --append-system-prompt <text-or-@file>
                         Anexa regras do operador ao prompt de sistema desta
                         execução: texto em linha, ou @caminho para um ficheiro
                         que as contenha. Aceita também --append-system-prompt=<value>;
                         a forma = é a a usar quando o caminho começa
                         com "-". As regras chegam como mais um bloco
                         de instrução pessoal delimitado, nunca uma substituição: não
                         podem substituir nem rebaixar as camadas acima delas, e
                         marcadores de bloco forjados no texto são neutralizados.
                         Limitado ao mesmo tamanho de um documento de instruções.
                         Apenas com -p ou o verbo run: um arranque sem
                         prompt para anexar recusa com saída 2 em vez de
                         ignorar silenciosamente as regras fornecidas.
  -c, --continue         Reabrir a sessão mais recentemente utilizada, transcrição
                         incluída, em vez de iniciar uma nova. Sem esta opção
                         cada arranque abre uma nova sessão; Up numa caixa
                         de entrada vazia ainda recupera prompts de sessões anteriores.
      --resume [<id|name>]
                         Reabrir uma sessão guardada por id, prefixo de id único ou
                         nome (ver `session list`). Sem valor, abre o seletor de
                         sessões no arranque; com -p, um destino É obrigatório
                         (a transcrição alimenta o one-shot e a resposta é guardada
                         de volta na linha). Aceita também
                         --resume=<id>. Não combinável com --continue.
      --worktree [<name>]
                         Executar toda a sessão dentro de um git worktree
                         main-<name> no branch candy-code/<name>, criado
                         na primeira utilização; sem nome, o worktree recebe um
                         escolhido automaticamente. Na saída, um worktree sem
                         commits nem edições é removido novamente; um com
                         trabalho fica e anuncia o seu caminho. Recusado
                         fora de um git work tree e com `serve`.
      --incognito        Arranque que não guarda nada: sem linha de sessão, sem
                         transcrição, sem escritas automáticas de memória no fim do turno.
                         O que a execução produziu vive apenas no processo;
                         sessões e notas guardadas ANTERIORMENTE permanecem legíveis.
                         Recusado com --continue ou --resume, que reabrem
                         sessões guardadas.
      --restricted       Arranque que não pode executar código: Bash, PtyRun, Task,
                         Workflow, ShellStop e mcp_call são removidos de
                         todos os conjuntos voltados ao modelo durante toda a sessão, e
                         /permissions não os pode restaurar. As ferramentas de ficheiro
                         permanecem, sob o confinamento de caminhos existente. Aceita também
                         --restricted=true|false, para que um wrapper possa ter
                         precedência sobre um alias com a flag simples. Sobrevive a reinício.
      --safe-mode        Arranque que ignora toda a confiança: cada raiz de
                         projeto confiável responde como não confiável (hooks, MCP
                         de projeto e shells de comandos), nenhum bundle é carregado, e nenhuma
                         skill, comando ou agente externo é descoberto.
                         Definições, skills e comandos nativos permanecem. Aceita
                         também --safe-mode=true|false para ter precedência sobre um
                         alias. Sobrevive a reinício.
  -h, --help             Mostrar esta mensagem de ajuda
  -v, --version          Mostrar a versão instalada e sair
      --                 Fim das opções: todo o argumento seguinte é posicional,
                         nunca uma flag

Variáveis de ambiente:
   CANDY_CODE_PROVIDER    Fornecedor a usar: openai, azure, anthropic, claude-code,
                          codex, sglang, bedrock, vertex, gemini,
                          openrouter, custom
   CANDY_CODE_MODEL       Nome do modelo (substitui a predefinição do fornecedor; --model tem precedência)
   CANDY_CODE_PERMISSION_MODE
                          Modo de permissões inicial, substituindo a
                          chave de configuração permissionMode (--permission-mode tem precedência)
   CANDY_CODE_BACKEND_CMD Comando de shell para um adaptador de backend personalizado, sob o
                          contrato PROSE: recebe histórico JSON em stdin, escreve
                          o texto da resposta em stdout, que é usado literalmente
                          (recortado apenas nas duas extremidades, por isso cada nova linha, linha em
                          branco e indentação interior sobrevive).
   CANDY_CODE_BACKEND_CMD_STREAM
                          A mesma execução externa sob o outro contrato, um TOKEN
                          STREAM: um token por linha, a nova linha entre dois
                          tokens é enquadramento e é descartada, e uma linha EM BRANCO é
                          uma nova linha literal na resposta. O callback dispara por
                          token à medida que o comando os produz, mas o ciclo de leitura
                          é síncrono, pelo que o ecrã é redesenhado uma vez no fim
                          em vez de token a token. Não intercambiável com
                          CANDY_CODE_BACKEND_CMD em qualquer direção — um wrapper
                          de prosa executado através desta variável regressa sem nenhuma
                          nova linha e com cada linha em branco reduzida a uma.
                          CANDY_CODE_BACKEND_CMD tem precedência sobre esta quando ambas estão definidas.
                          Para ambas, não definida, vazia e apenas espaços em branco
                          contam como ausente.
   CANDY_CODE_DISABLE_PARALLEL_TOOL_CALLS
                          Executar as chamadas de ferramentas de um turno estritamente uma de cada vez.
                          O despacho concorrente é a predefinição e apenas
                          agrupa ferramentas não mutáveis; esta é a válvula de escape.
                          Persistir como "parallelToolCalls": false em
                          ~/.candy-code/config.json.
   CANDY_CODE_PARALLEL_TOOL_DEADLINE
                          Segundos que um grupo concorrente pode executar antes de os seus
                          atrasados serem terminados e reportados como chamadas falhadas
                          (predefinição 90, deve ser 1-119; uma fração é truncada).
                          Persistir como "parallelToolDeadlineSeconds".
                          Precedência: esta variável, depois a chave persistida,
                          então o valor predefinido. Um valor fora de 1-119, ou um que
                          não seja de todo um número, não conta como definido —
                          passa ao próximo recurso em vez de
                          o descartar.
   CANDY_CODE_ADVISOR_MODEL
                          O modelo que a ferramenta `Advisor` consulta para uma
                          segunda opinião: uma conclusão sem ferramentas, faturada
                          como qualquer outra chamada. Ao contrário de CANDY_CODE_TITLE_MODEL, não
                          existe alternativa económica — não definido significa que a
                          ferramenta não é oferecida de todo. Lido no arranque.
   CANDY_CODE_TITLE_MODEL O modelo económico usado para nomear automaticamente uma sessão após
                          a sua primeira troca; por omissão, o do fornecedor.
   CANDY_CODE_SUMMARY_MODEL
                          O modelo que escreve resumos de compactação;
                          por omissão, o da própria conversa, o que reutiliza
                          a cache de prompts.
   CANDY_CODE_CONTEXT_PRUNING
                          auto, manual ou off: como uma sessão poda o seu
                          contexto quando /pruning não escolheu (por omissão: auto).
   CANDY_CODE_MAX_COST    Um teto de despesa para este arranque, em dólares
                          (decimais permitidos; um "$" inicial é aceite;
                          --max-cost prevalece). Um turno que ultrapasse o teto
                          é recusado.
   CANDY_CODE_CONNECT_TIMEOUT
                          Limite da fase de ligação, em segundos (decimais
                          permitidos; por omissão 15.0), para os transportes
                          HTTP do fornecedor. Limita apenas o estabelecimento da
                          ligação — não é um tempo limite total do pedido. O tempo
                          que um servidor em streaming conectado pode demorar a enviar
                          os seus cabeçalhos de resposta é a definição
                          streamHeaderTimeoutSeconds, separada.
   CANDY_CODE_SEARCH_ENDPOINT
                          API de pesquisa que a ferramenta WebSearch integrada consulta.
   CANDY_CODE_SESSION_RETENTION_DAYS
                          Um número inteiro positivo de dias: cada arranque elimina
                          sessões intocadas durante pelo menos esse tempo.
   CANDY_CODE_SHARE_UPLOAD_URL
                          Anfitrião de carregamento desativado: /share nunca carrega
                          para lado algum. Quando definido, a exportação local ainda
                          é gerada e a resposta recusa ruidosamente a chave e indica
                          /share serve, que publica uma página de instantânea
                          auto-hospedada no seu próprio candy-code serve.
   CANDY_CODE_WORKTREES_DIR
                          Diretório base sob o qual são criados os worktrees
                          git por colega de equipa.
   CANDY_CODE_DISABLE_MOUSE
                          Qualquer valor diferente de vazio ou 0 desativa
                          por completo o rastreamento do rato.
   CANDY_CODE_DISABLE_MOUSE_CLICKS
                          Qualquer valor diferente de vazio ou 0 ignora gestos
                          de clique mantendo o deslocamento com a roda.
   CANDY_CODE_DISABLE_PROMPT_CACHE
                          Qualquer valor diferente de vazio ou 0 desativa os
                          pontos de quebra de cache de prompts do fornecedor.
   CANDY_CODE_DISABLE_PROMPT_SUGGESTIONS
                          Qualquer valor diferente de vazio ou 0 interrompe a
                          sugestão de mensagem seguinte esbatida (→ aceita-a) após cada turno.
   CANDY_CODE_DISABLE_AUTO_MEMORY
                          Qualquer valor diferente de vazio ou 0 interrompe a
                          auto-memória: guardar factos duráveis como notas após um turno, e
                          a passagem de sonho a integrar o diário de compactação
                          nessas notas.
   CANDY_CODE_DISABLE_MODEL_METADATA
                          Qualquer valor diferente de vazio ou 0 interrompe a leitura e
                          atualização da base de dados de modelos LiteLLM que dimensiona e
                          precifica modelos sem valor incorporado.
   CANDY_CODE_NO_UPDATE_CHECK
                          Qualquer valor diferente de vazio ou 0 interrompe a verificação diária
                          de versões phar e o aviso de atualização no arranque que alimenta;
                          nenhum pedido sai do processo e um aviso em cache
                          desatualizado deixa de ser exibido.
   CANDY_CODE_DISABLE_SYMBOL_MAP
                          Qualquer valor diferente de vazio ou 0 mantém o mapa
                          de símbolos ordenado fora do prompt de sistema.
   CANDY_CODE_BACKGROUND  light ou dark — força o que o tema adaptativo
                          assume sobre o fundo do terminal, ignorando
                          a sonda OSC 11 e COLORFGBG.
   CANDY_CODE_DEBUG_SKILLS
                          Qualquer valor diferente de vazio ou 0 repõe no
                          stderr as linhas por-skip e por-diretória-recusada do SkillLoader.
                          stderr.
   CANDY_CODE_DEBUG_COMMANDS
                          Qualquer valor diferente de vazio ou 0 repõe no stderr as
                          linhas de recusa de descoberta do CommandLoader.
   CANDY_CODE_DEBUG_RULES Qualquer valor diferente de vazio ou 0 repõe no stderr as
                          linhas de recusa de descoberta do RuleLoader.
   CANDY_CODE_DEBUG_STREAM
                          Qualquer valor diferente de vazio ou 0 mantém no stderr a
                          linha "onToken observer threw" do Chat. A
                          separação em si acontece de qualquer forma.
   CANDY_CODE_SERVER_HOST O endereço a que o `serve` se associa (--host vence).
   CANDY_CODE_SERVER_PORT A porta a que o `serve` se associa (--port vence).
   CANDY_CODE_SERVER_ALLOWED_ORIGINS
                          Origens adicionais separadas por vírgula que o `serve` aceita
                          (--allowed-origin vence).
   CANDY_CODE_SERVER_ALLOWED_HOSTS
                          Nomes de host adicionais separados por vírgula a que o `serve` responde
                          (--allowed-host vence).
   CANDY_CODE_SERVER_ALLOWED_IPS
                          IPs de cliente ou CIDRs separados por vírgula que o `serve` admite
                          além do loopback (--allowed-ips vence).
   CANDY_CODE_SERVER_WEB_ROOT
                          Diretório de onde o `serve` serve a interface web (--web-root
                          vence).
   CANDY_CODE_SERVER_TOKEN
                          O token que o `serve` exige, em vez do que está no
                          seu diretório de estado (pelo menos 32 caracteres; para
                          contentores).
   CANDY_CODE_SERVER_DIR  O diretório onde o `serve` guarda o seu token, lock,
                          registo de descoberta e log (predefinição
                          ~/.candy-code/server; criado com 0700).
   CANDY_CODE_SERVER_PARENT_PID
                          Um processo que o `serve` termina com (--parent-pid vence).
   CANDY_CODE_MCP_DISABLE
                          1, true ou yes (sem distinção de maiúsculas) silencia o MCP
                          do projeto por completo: .mcp.json é tratado como inexistente, nenhum
                          servidor arranca. Não definido, 0 ou qualquer outro valor mantém
                          o MCP ativo — ao contrário das variáveis de estilo flag,
                          apenas estas três palavras contam.
   CANDY_CODE_QUIET_LOGS  1, true ou yes (sem distinção de maiúsculas) silencia o
                          canal lateral error_log() a nível de processo no seu único
                          destino; não definido, 0 ou qualquer outro valor mantém os
                          diagnósticos ativos. Apenas no arranque, sem chave de configuração.
   CANDY_CODE_REDUCED_MOTION
                          1, true ou yes (sem distinção de maiúsculas) fixa o
                          spinner do agente num único quadro estático — para utilizadores
                          sensíveis a movimento e com movimento reduzido. Lido uma vez no
                          arranque; não existe chave de configuração.
   CANDY_CODE_SD_BASE_URL URL base do servidor Stable Diffusion estilo A1111 (sdapi)
                          que o transporte de media contacta.
                          Precedência: uma sobreposição explícita no código, depois esta
                          variável, depois a definição sd.baseUrl.
   CANDY_CODE_MEDIA_RENDER_MODE
                          Como as imagens geradas são desenhadas no terminal
                          (a camada de ambiente da definição ui.imageRenderMode; ver
                          docs/ENVIRONMENT.md para as palavras aceites).
   CANDY_CODE_ALLOW_ROOT_TESTS
                          Definir exatamente como 1 para permitir que a SUÍTE DE TESTES
                          do candy-code execute como root; não definido ou qualquer outro valor, a suíte
                          recusa-se a arrancar com euid 0. Nada muda no arranque do
                          candy-code — a suíte não é uma
                          interface para o utilizador.
   CANDY_CODE_TOOL_INPUT  O mapa completo de argumentos da chamada de ferramenta de script do utilizador atual,
                          codificado em JSON, exportado para o processo filho
                          de cada execução de uma ferramenta ~/.candy-code/tools;
                          a aplicação escreve-o, nunca o lê de volta, e
                          ninguém o define diretamente.
   CANDY_CODE_OTEL_BATCH_SIZE
                          Quantos spans um lote de exportação OTLP transporta
                          (predefinição 64, limitado a 1..2048).
   CANDY_CODE_OTEL_TIMEOUT
                          Segundos que cada tentativa de exportação OTLP pode demorar
                          (predefinição 3; um valor não positivo ou malformado
                          recorre à predefinição).

   docs/ENVIRONMENT.md tabula todas as variáveis que esta compilação lê, com o seu
   contrato completo.

Códigos de saída (modo one-shot e todos os subcomandos):
  0                      O prompt foi executado e produziu uma resposta, ou o
                         subcomando respondeu
  1                      Executado e falhou: o backend lançou (host inacessível,
                         chave rejeitada, erro de modelo) — uma nova tentativa pode ajudar — ou um
                         subcomando foi executado e falhou (uma verificação doctor devolveu
                         FAIL, um verbo `session` não encontrou essa sessão, um
                         .mcp.json de confiança não pôde ser analisado)
  2                      Erro de utilização ou configuração, nada foi tentado
                         e uma nova tentativa não ajudará: nenhum prompt fornecido, uma
                         flag não reconhecida, um argumento isolado que não nomeia nenhum
                         diretório existente (um prompt precisa de -p), um --root
                         que não nomeia nenhum diretório, um composer
                         autoload.php em falta, ou um provider selecionado
                         que não pode ser construído — seja
                         $CANDY_CODE_PROVIDER ou o provider persistido em
                         ~/.candy-code/config.json por Ctrl+P "Switch model".
                         Uma execução one-shot nunca recorre ao provider offline echo
                         quando um provider foi selecionado explicitamente.
                         Um subcomando com um operando em falta ou desconhecido
                         (`session`, `mcp bogus`, `completion tcsh`) reporta
                         aqui também.
  130/143/129             TUI: um sinal interrompeu o ciclo — 128+N para
                         SIGINT (Ctrl+C), SIGTERM, SIGHUP; uma saída
                         cooperativa (/exit, q) sai ainda com 0.

Exemplos:
  candy-code -p "Explica a diferença entre require e include"
  CANDY_CODE_PROVIDER=anthropic CANDY_CODE_MODEL=claude-sonnet-4-20250514 \
    candy-code -p "Escreve um hello world em Go"
  candy-code run "Escreve um hello world em Go"
  candy-code doctor
  candy-code models --output-format json | jq '.result.providers'
  eval "$(candy-code completion bash)"
  candy-code serve --port 7420

Para mais informações, consulte o README:
  https://github.com/detain/sugarcraft/tree/master/candy-code

