    'cli.references.unusable' => 'uma entrada `references` não pôde ser lida — deve ser um objeto com um `path` (ou uma cadeia de caminho simples); esta entrada foi ignorada.',
    'cli.refuse.bad_mode' => '{source} é \'{value}\', que não é um modo de permissão (esperava-se um de: {valid}). A recusar iniciar em vez de recorrer ao padrão permissivo.',
