    'cli.refuse.config_unreachable' => '{path} não pode ser alcançado: {reason}, pelo que não é possível saber se existe uma política de permissões configurada. A recusar iniciar em vez de executar com uma política de permissões desconhecida.',
    'cli.refuse.config_unreadable' => '{path} existe mas não pôde ser lido (verifique as suas permissões). A recusar iniciar em vez de executar com uma política de permissões desconhecida.',
    'cli.refuse.dangling_directory' => '{dir} é uma ligação simbólica que não resolve para um diretório que este processo possa pesquisar',
    'cli.refuse.foreign_owner' => '{path} pertence ao uid {uid}, não à conta com que esta sessão está a ser executada, pelo que a política de permissões e a cadeia de hooks que transporta pertencem a outra pessoa. A recusar iniciar em vez de executar a política de outra conta.',
    'cli.refuse.hook_chain' => '{error} A recusar iniciar em vez de executar com uma cadeia de hooks que não é a configurada.',
    'cli.refuse.hooks_unreachable' => '{path} não pode ser alcançado: {reason}, pelo que não é possível saber se existem hooks configurados. A recusar iniciar em vez de executar com uma cadeia de hooks desconhecida.',
    'cli.refuse.keybindings' => 'a definição de atalhos de teclado é inutilizável: {reason}. Remova a chave para executar com os atalhos incluídos (a referência /keys nomeia-os). A recusar iniciar em vez de executar com substituições de teclas que não recebeu.',
    'cli.refuse.max_cost_env' => '$CANDY_CODE_MAX_COST é \'{value}\', que não é um limite de despesa. Esperava-se um número positivo de dólares americanos (decimais permitidos, um $ inicial aceite), por exemplo 5 ou $2.50. Zero e negativos são recusados em vez de interpretados como "sem limite" porque são o pedido oposto; um valor demasiado grande para ser representado (1e309, ou seja, infinito) é recusado porque instalaria um limite que nunca se ativa. Desative a variável para não ter limite. A recusar iniciar em vez de executar sem limite com um teto que pediu.',
    'cli.refuse.max_cost_flag' => '--max-cost é \'{value}\', que não é um limite de despesa. Esperava-se um número positivo de dólares americanos (decimais permitidos, um $ inicial aceite), por exemplo 5 ou $2.50. Zero e negativos são recusados em vez de interpretados como "sem limite" porque são o pedido oposto; um valor demasiado grande para ser representado (1e309, ou seja, infinito) é recusado porque instalaria um limite que nunca se ativa. Remova a bandeira para não ter limite. A recusar iniciar em vez de executar sem limite com um teto que pediu.',
    'cli.refuse.max_cost_setting' => 'maxCostUsd nas suas definições é {value}, que não é um limite de despesa. Esperava-se um número positivo de dólares americanos, por exemplo 5 ou 2.5. Remova a chave para não ter limite. A recusar iniciar em vez de executar sem limite com um teto que pediu.',
    'cli.refuse.max_turns_flag' => '--max-turns é \'{value}\', que não é um limite de passos. Esperava-se um número inteiro positivo de passos do ciclo de ferramentas, por exemplo 8. Zero é recusado em vez de interpretado como "sem limite" porque é o pedido oposto; um valor demasiado grande para ser representado é recusado porque instalaria um limite que nunca se ativa. Remova a bandeira para recorrer à definição maxToolSteps. A recusar iniciar em vez de executar sem limite com um teto que pediu.',
    'cli.refuse.no_home' => 'este processo não consegue determinar qual é o seu diretório pessoal ($HOME não está definido, $USERPROFILE não está definido e não existe entrada no passwd para o seu uid), pelo que a política de permissões e a cadeia de hooks em ~/.candy-code não podem ser localizadas. A recusar iniciar em vez de ler qualquer uma delas a partir de um diretório de recurso gravável por todos — exporte HOME para a conta a que esta sessão pertence.',
    'cli.refuse.no_project_root' => 'não é possível determinar a raiz do projeto — o diretório de trabalho do processo está indisponível (apagado ou ilegível). Passe --root <dir>.',
    'cli.refuse.not_searchable' => '{dir} não é pesquisável por este processo',
    'cli.refuse.project_settings_unusable' => '{path} não pôde ser lido para obter as suas permissionRules ({reason}). A recusar iniciar em vez de executar com uma política de permissões desconhecida.',
    'cli.refuse.world_writable' => '{path} é gravável por todas as contas nesta máquina, pelo que a política de permissões e a cadeia de hooks que transporta não pertencem a este utilizador. A recusar iniciar em vez de executar uma política que qualquer pessoa poderia ter escrito — `chmod o-w {path}`.',
