    'cli.selfupdate.composer_mode_root' => 'candy-code: self-update substitui uma instalação phar, e esta cópia é o pacote sugarcraft/candy-code instalado como raiz do Composer — não existe aqui nenhum phar para trocar, e um pacote raiz não pode atualizar-se através do seu próprio comando de dependências. Atualize-o com: {command} (o clone obtém o novo código-fonte e depois reconstrói a árvore de fornecedores).',
