    'cli.selfupdate.sig.deprecated' => 'candy-code: este lançamento assina os bytes brutos do phar com {asset}; essa etapa legida lê todo o artefacto para a memória e é aceite por mais um ciclo de lançamento. Publique {replacement} — uma assinatura Ed25519 sobre o corpo do sidecar sha256 — para que a verificação nunca saia do fluxo.',
