    'cli.selfupdate.signature_missing' => 'candy-code: este lançamento não contém {asset} nem {sig_sidecar}, e a chave de lançamento fixada exige um para {phar}. Nada foi trocado (--allow-unsigned é o contorno exclusivo de dev).',
    'cli.selfupdate.staged_windows' => 'candy-code: a atualização está preparada para a dança de reinício — {new} troca para {path} quando este processo terminar; o progresso é registado em {path}.swap.log e a cópia guardada permanece em {old}.',
    'cli.selfupdate.swap_leftover' => 'candy-code: um self-update anterior deixou uma troca preparada em {new} que nunca foi aplicada (o seu registo de troca documenta as tentativas abandonadas). Esta execução substitui a preparação antes de atualizar.',
    'cli.selfupdate.swap_spawn_failed' => 'candy-code: o auxiliar de troca não pôde ser iniciado; os bytes verificados permanecem preparados em {new} e a cópia em execução está intacta. Conclua a renomeação para {path} manualmente, ou volte a executar self-update quando nada estiver a reter o ficheiro.',
    'cli.selfupdate.uncomparable' => 'candy-code: esta instalação reporta {current}, que não é uma versão de lançamento que self-update possa ordenar.',
    'cli.selfupdate.unexpected_operand' => '{operand}: candy-code self-update não aceita operandos.',
