    'cmd.mcp-auth.disable.done' => '✓ `{server}` desativado para esta sessão — chamadas recusadas a partir do próximo turno; o catálogo voltado para o modelo não é rederivado (lei da cache), pelo que as suas ferramentas permanecem listadas até reiniciar.',
