    'cmd.mcp-auth.empty' => "Sem credenciais MCP armazenadas.\n\nAs credenciais destinam-se apenas a servidores que exigem início de sessão OAuth; um\nservidor http declarado que não precisa de nenhuma funciona apenas com o seu \"url\".\nOs servidores em si são declarados sob \"mcpServers\" em\n<project>/.mcp.json — receita: docs/MCP.md, \"{section}\".",
    'cmd.mcp-auth.enable.done' => '✓ `{server}` ativado para esta sessão — recusas de sessão levantam-se a partir do próximo turno; chamadas são reencaminhadas apenas onde o encaminhamento de arranque já permite o nome.',
