    'cmd.mcp-auth.failed' => '✗ Registo falhou: {error}',
    'cmd.mcp-auth.heading' => '**Servidores MCP**',
    'cmd.mcp-auth.login-armed' => "↻ Início de sessão MCP iniciado para `{server}` — à espera do link do navegador.\n\nO processo filho vincula uma porta de loopback; conclua-o num navegador enquanto a TUI permanece responsiva. O cliente MCP desta sessão memorizou o seu armazenamento no arranque, pelo que o token entra em efeito no PRÓXIMO arranque; `/mcp list` mostra a credencial assim que for armazenada.",
    'cmd.mcp-auth.login-busy' => '! Um início de sessão para `{server}` já está em execução — conclua ou cancele esse primeiro (o seu URL e estado estão na transcrição acima).',
    'cmd.mcp-auth.login-code-delivered' => '✓ O callback foi entregue ao início de sessão à espera para `{server}` — o processo filho conclui a troca ali, e o seu resultado aparece na transcrição.',
    'cmd.mcp-auth.login-code-refused' => '! Não foi possível entregar o callback de início de sessão MCP para `{server}`: {reason}',
    'cmd.mcp-auth.login-code-reason-dial' => "o ouvinte do início de sessão à espera não respondeu",
    'cmd.mcp-auth.login-code-reason-host' => 'apenas os hosts de loopback `127.0.0.1` e `localhost` são aceites',
    'cmd.mcp-auth.login-code-reason-noslot' => 'nenhum início de sessão para esse servidor está atualmente à espera neste host',
    'cmd.mcp-auth.login-code-reason-port' => 'a porta não corresponde à porta de callback anunciada pelo início de sessão à espera',
    'cmd.mcp-auth.login-code-reason-scheme' => 'o URL de callback deve usar o esquema `http` simples ao qual o ouvinte de início de sessão se vincula',
    'cmd.mcp-auth.login-code-reason-shape' => 'o formato é `/mcp login <server> --code <callback-url>` com exatamente um URL',
    'cmd.mcp-auth.login-done' => '✓ Início de sessão MCP para `{server}` concluído (saída {code}). Tokens anexam-se no PRÓXIMO arranque — inicie uma nova sessão para que a concessão acompanhe as requisições; `/mcp list` atualiza o painel.',
    'cmd.mcp-auth.login-failed' => <<<'TXT'
✗ Início de sessão MCP para `{server}` terminou com {code} sem armazenar tokens.

As últimas linhas do processo filho estão acima; o mesmo fluxo num shell (`candy-code mcp auth login {server}`) imprime o erro completo e é o lugar para depurar problemas de endpoint ou porta.
TXT,
    'cmd.mcp-auth.login-failed-spawn' => "✗ Não foi possível iniciar o processo filho de início de sessão MCP para `{server}`.\n\nExecute a forma de shell diretamente: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-guidance' => "O início de sessão interativo é um comando de shell, não um turno de conversa:\n\n  candy-code mcp auth login <server> [token-url] [authorize-url] [registration-url]\n\nExecuta o fluxo de código de autorização OAuth com PKCE: o seu navegador\ndevolve o código a um listener de loopback na shell, e os tokens\narmazenados são anexados a servidores http correspondentes a partir do próximo arranque.",
    'cmd.mcp-auth.login-no-entry' => "✗ Não foi possível encontrar o ponto de entrada deste programa para fazer fork de `mcp auth login {server}`.\n\nExecute a forma de shell diretamente: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-served-armed' => "↻ Início de sessão MCP para `{server}` no host do SERVIDOR — a ligação aparece abaixo; abra-a num navegador na sua máquina. O seu navegador não consegue aceder diretamente ao listener de loopback do servidor: quando chegar a uma página de erro de ligação, copie o endereço dessa página e envie `/mcp login {server} --code <that-url>` para entregar o callback ao início de sessão em espera. Os tokens são anexados no PRÓXIMO arranque; `/mcp list` mostra a credencial assim que for armazenada.",
    'cmd.mcp-auth.login-url' => '→ Abra este URL para autorizar `{server}`:\n\n  {url}',
    'cmd.mcp-auth.not-found' => '! Nenhuma credencial encontrada para `{server}`.',
    'cmd.mcp-auth.registered' => <<<'TXT'
✓ `{server}` registado com sucesso
Client ID: `{client}`
As pedidos a um servidor MCP http com este URL exato passam agora a transportar este token automaticamente, renovado antes da expiração; os servidores iniciados antes deste comando captam-no no próximo arranque.
TXT,
    'cmd.mcp-auth.remove-usage' => 'Utilização: mcp auth remove <server>',
    'cmd.mcp-auth.reconnect.auth' => '! `{server}` reporta agora que necessita de um início de sessão OAuth.',
    'cmd.mcp-auth.reconnect.denied' => '! `{server}` é recusado por um padrão de recusa.',
    'cmd.mcp-auth.reconnect.drifted' => "Configuração MCP alterada desde o arranque — reconexão recusada. Uma reconexão reinicia os servidores exatamente como `.mcp.json` os contém agora, enquanto esta sessão foi admitida com base nos bytes em que o arranque confiou; iniciar entradas desviadas executaria servidores que as decisões de admissão nunca viram. Reinicie a sessão para aplicar a alteração; esse é o único caminho de aplicação.",
    'cmd.mcp-auth.reconnect.error' => 'Falha ao iniciar: {error}',
    'cmd.mcp-auth.reconnect.heading' => '**Reconnected MCP servers**',
