    'cmd.mcp-auth.reconnect.unknown' => 'Esta sessão não registou nenhum resumo de arranque para `.mcp.json`, pelo que uma reconexão não pode provar que a configuração ainda contém os bytes de que o arranque partiu — recusada, reiniciar é o único caminho de aplicação.',
    'cmd.mcp-auth.removed' => '✓ Credenciais removidas de `{server}`',
    'cmd.mcp-auth.status.active' => '● ativo',
