    'cmd.mcp-auth.status.expiring' => '● a expirar em breve',
    'cmd.mcp-auth.status.none' => '○ sem credenciais',
    'cmd.mcp-auth.undiscovered' => "! Não foi possível descobrir endpoints OAuth para `{server}`.\n\nForneça-os explicitamente:\n  `mcp auth add {server}` *<registration-url>* *<token-url>*\n\nNada a descobrir costuma significar nada a registar: um\nservidor que não precisa de início de sessão funciona apenas com o seu \"url\" uma vez\ndeclarado em .mcp.json (docs/MCP.md, \"{section}\").",
    'cmd.mcp-auth.unknown' => 'Subcomando desconhecido \'{sub}\'. Utilize: list, add, remove, login, reconnect, enable, disable',
    'cmd.mcp-auth.usage' => "Utilização:\n  mcp auth list                    — listar servidores registados\n  mcp auth add <server> [reg-url] [token-url]  — armazenar credenciais OAuth de um servidor\n  mcp auth remove <server>         — remover as credenciais de um servidor\n  mcp auth login <server>          — imprimir o comando de shell para início de sessão interativo\n  /mcp reconnect                   — reiniciar os servidores declarados, apenas enquanto .mcp.json corresponder ao arranque\n  /mcp enable <server> [--persist]   — levantar a recusa desta sessão a um servidor declarado\n  /mcp disable <server> [--persist]  — recusar as chamadas de um servidor declarado nesta sessão",
    'cmd.mcp.description' => 'Gerir autenticação de servidores MCP (list/add/remove; login imprime o comando CLI) e ativar/desativar por sessão',
