    'sandbox.hook.not_run' => 'Não executado: o hook `{hook}` está confinado à sandbox `{mode}` por sandboxScope, mas a sandbox {name} não pode iniciar neste host ({reason}). Nada foi executado, em sandbox ou não. Informe o utilizador: pode corrigir {name} ({remedy}) ou definir bashSandbox como "off".',
    'sandbox.lsp.not_started' => 'Não iniciado: o servidor de linguagem `{language}` ({command}) está confinado à sandbox `{mode}` por sandboxScope, mas a sandbox {name} não pode iniciar neste host ({reason}). Nada foi iniciado, em jail ou não. Informe o utilizador: pode corrigir {name} ({remedy}), definir bashSandbox como "off", ou isentar este servidor com `"sandbox": false` na sua própria entrada `lsp`.',
    'sandbox.mcp.not_started' => 'Não iniciado: o servidor MCP `{server}` está confinado à sandbox `{mode}` por sandboxScope, mas a sandbox {name} não pode iniciar neste host ({reason}). Nada foi iniciado, em jail ou não. Informe o utilizador: pode corrigir {name} ({remedy}), definir bashSandbox como "off", ou isentá-lo com `"sandbox": false` na sua entrada de nível de utilizador.',
    'sandbox.mcp.opt_out_ignored' => 'Ignorado: a isenção `"sandbox": false` no(s) servidor(es) MCP {servers} não veio do ficheiro de definições do utilizador — apenas o nível de utilizador pode isentar um servidor stdio da jail sandboxScope. O(s) servidor(es) fica(m) em jail conforme o âmbito.',
