    'chat.command.error' => '**Erro:** {error}',
    'chat.compact.idle_advisory' => 'Esta sessão está ociosa há mais de uma hora e cresceu para ~{tokens} tokens estimados, ultrapassando a janela de contexto de {limit} tokens. Execute /compact para reduzir o contexto antes de continuar. Enviar outra mensagem não a enviará tal como está: a próxima interação está acima do nível de compactação automática, pelo que as trocas mais antigas são resumidas primeiro, e a interação é recusada se isso não libertar espaço suficiente.',
    'chat.compact.idle_auto_scheduled' => 'Compactação automática por inatividade: a sessão ultrapassou a janela de inatividade com a transcrição acima do nível de compactação (~{tokens} tokens estimados numa janela de {limit} tokens), pelo que o pedido de resumo foi enviado sem intervenção. A dobra é aplicada na próxima interação; nada é faturado duas vezes e nenhuma resposta é enviada a ninguém.',
