    'chat.turn.loop_guard' => 'Este turno foi terminado pelo guardião de ciclo de chamadas repetidas: o modelo chamou {tool} {count} vezes com os mesmos argumentos e obteve o mesmo resultado em cada uma. A resposta acima descreve onde parou. Indique uma abordagem diferente, ou escreva `continue` quando algo tiver mudado.',
    'chat.turn.output_limit' => 'O fornecedor interrompeu esta resposta no seu limite de saída, pelo que o texto acima pode terminar a meio de um pensamento. Aumente `maxOutputTokens` em ~/.candy-code/config.json para uma resposta única mais longa, ou peça o restante na sua próxima mensagem.',
    'chat.turn.steps_exhausted' => 'Este turno esgotou todos os seus passos de ferramentas antes de o trabalho estar concluído, pelo que a resposta acima descreve onde parou — o que está terminado e o que falta — não uma resposta final. Escreva `continue` para retomar de onde ficou, ou aumente o teto para turnos agênticos mais longos — a flag --max-turns no arranque prevalece sobre a definição `maxToolSteps` em ~/.candy-code/config.json, pelo que aumente a que estiver em vigor.',
    'chat.turn.unpriced_model' => 'Esta aplicação não tem preço registado para o modelo `{model}`, pelo que este turno foi faturado em $0.00 como limite inferior, não como chamada gratuita — os totais de despesa e o teto de despesa ficam subavaliados até existir uma tarifa. Declare uma em `modelPrices` em ~/.candy-code/config.json (USD por 1M tokens, chaves `input` e `output`) para o precificar.',
    'chat.verbose.failed' => 'Alternância de verbosidade recusada: {error}',
    'chat.verbose.off' => 'Saída verbos de ferramentas desativada — linhas voltam a colapsar · apenas esta sessão, nada escrito',
    'chat.verbose.on' => 'Saída verbos de ferramentas ativada — linhas permanecem expandidas · apenas esta sessão, nada escrito',
    'chat.verbose.unsavable' => 'Nada aqui guarda definições, pelo que a alternância de verbosidade não pode mudar',
    'chat.voice.busy' => 'Outra gravação de voz ainda está a ser transcrita — esta foi descartada, nada foi guardado',
    'chat.voice.recording' => '● rec · Alt+V parar · Esc cancelar',
    'chat.voice.transcribing' => 'a transcrever…',
    'chat.workflow.cancelled' => '_Fluxo de trabalho cancelado: a parar os seus agentes. O relatório segue-se._',
    'host.agents.accept.bad_name' => '`{name}` não é um nome de rascunho. Um rascunho é um ficheiro diretamente no diretório de rascunhos, e passa o seu nome — letras minúsculas, dígitos, pontos, underscores e hífens — a /agents accept.',
    'host.agents.accept.exists' => 'Já existe uma predefinição chamada {name} em {dir}/, e /agents accept nunca substitui uma predefinição ativa. Elimine ou renomeie essa predefinição primeiro, ou /agents new um rascunho com outro nome.',
    'host.agents.accept.frontmatter' => 'O rascunho {name} não tem bloco de frontmatter que seja interpretado como um mapeamento, pelo que não foi promovido. Execute /agents new novamente, ou corrija o ficheiro e aceite-o outra vez.',
    'host.agents.accept.missing' => 'Nenhum rascunho chamado {name} em {dir}/. Execute /agents new para criar um, ou /agents proposed para listar os rascunhos.',
    'host.agents.accept.mode' => 'O rascunho {name} declara `permissionMode: {mode}`, que não é um dos modos desta porta. Declare um de: {modes} — ou omita a chave para `default`.',
    'host.agents.accept.moved' => 'O rascunho {name} é agora {path} — o catálogo da próxima sessão carrega-o como predefinição de projeto.',
    'host.agents.accept.policy' => 'Política que este rascunho declara (impressa literalmente antes da mudança):',
    'host.agents.accept.policy_line' => '  - {key}: {value}',
    'host.agents.accept.self_grant' => '**Heads-up:** `{mode}` é uma autoconcessão — a predefinição promovida inicia execuções com uma superfície de permissões muito mais ampla do que uma sessão normal. Promovê-la aqui é o seu consentimento; o rascunho em si não a podia conceder.',
    'host.agents.accept.type' => 'O rascunho {name} declara `{key}` como um valor que o leitor de predefinições não consegue tipar — espera uma cadeia de caracteres ou uma lista de cadeias de caracteres.',
    'host.agents.accept.unknown' => 'O rascunho {name} declara `{key}`, uma chave sobre a qual nenhum leitor de predefinições atua{hint}. Remova-a ou corrija a grafia; /agents accept promove apenas ficheiros cujas chaves esta porta lê.',
    'host.agents.error' => 'O comando /agents draft falhou: {error}',
    'host.agents.new.dispatched' => 'A pedir ao agente que elabore uma predefinição a partir desta conversa; escreve apenas no nível de rascunho, e nada é promovido até executar /agents accept.',
    'host.agents.proposed.heading' => 'Rascunhos de agentes propostos:',
    'host.agents.proposed.none' => 'Sem rascunhos à espera em {dir}/. Execute /agents new para que o agente elabore um a partir desta conversa.',
    'host.agents.usage' => 'Utilização: /agents [list|<name>|use <preset|default>|new <focus>|proposed|accept <name>]',
    'host.agents.not_configured' => 'Gestor de agentes não configurado — nenhum runtime de sub-agente está associado a esta execução, pelo que /agents não pode iniciar nem vigiar agentes. Uma execução simples de `candy-code` tem sempre um; uma compilação de integração com host deve associá-lo.',
    // C-AGT-4.b: the `use` verb. Soft-appended after the block's last row;
    // rows answer `/agent use <preset|default>` and the Alt+A cycle.
    'host.agents.use_default' => 'De volta à predefinição simples da sessão — nada do que um /agent use anterior restringiu permanece aplicado.',
    'host.agents.use_switched' => '{name} é agora o agente primário desta sessão — as suas ferramentas, modelo e piso de permissões mantêm-se até voltar a mudar; um reinício executa a predefinição simples da sessão.',
    'host.agents.use_turn_running' => 'Um turno está em execução — o agente primário muda entre turnos, como um comutador de modo de permissão.',
    'host.agents.use_unavailable' => 'Esta sessão executa um backend de eco simples; não há lista de ferramentas nem filtro para um agente primário restringir.',
    'host.agents.use_unknown' => 'Nenhuma predefinição de lista chamada {name}. Execute /agents para ver a lista.',
    'host.bg.active' => 'Sessões em segundo plano ativas: {sessions}',
    'host.bg.backgrounded' => 'Executado em segundo plano como {id} (\'{name}\') — use /agents para verificar o estado, /bg stop {id} para cancelar.',
    'host.bg.default_name' => 'Tarefa em segundo plano',
    'host.bg.forked' => 'Bifurcado para sessão em segundo plano {id} (\'{name}\') — use /agents para verificar o estado, /bg stop {id} para cancelar.',
    'host.bg.none_active' => 'Sem sessões em segundo plano ativas.',
    'host.bg.not_configured' => 'Sessões em segundo plano não configuradas — esta execução não pode correr tarefas fora do primeiro plano. Uma execução simples de `candy-code` tem sempre o supervisor; uma compilação de integração com host deve associar um antes de /bg e /fork funcionarem.',
    'host.bg.start_failed' => 'Não foi possível iniciar a sessão em segundo plano \'{name}\': {error}',
    'host.bg.stop.already_finished' => 'A sessão em segundo plano {session} já tinha terminado; nada para parar.',
    'host.bg.stop.failed' => 'Não foi possível parar a sessão em segundo plano {session}: {error}',
    'host.bg.stop.signalled' => 'Sessão em segundo plano {session} parada (o seu socket de controlo desapareceu, pelo que o daemon foi sinalizado).',
    'host.bg.stop.stopped' => 'Sessão em segundo plano {session} parada.',
    'host.bg.stop.unknown' => 'Nenhuma sessão em segundo plano {id} nesta execução — /bg stop lista as ativas.',
    'host.bg.stop.unreachable' => 'Não foi possível parar a sessão em segundo plano {session} — o seu daemon não pôde ser alcançado nem sinalizado com segurança.',
    'host.bg.stop_usage' => 'Utilização: /bg stop <session-id>',
    'host.bg.usage' => 'Utilização: /bg <task>',
    'host.command_shell.bundle_refused' => '[!`{command}` não foi executado: /{name} veio de um pacote de plugin, um pacote empacotado por outra pessoa. Uma linha de pacote recusa formas de shell a menos que indique o nome do pacote sob "trustedBundleCommands" na sua própria configuração de utilizador — e essa abertura só conta para pacotes a nível de utilizador: uma checkout de projeto não pode conceder shell a si mesma, nem sequer usurpando um nome listado — o resto do comando foi enviado.]',
    'host.command_shell.mcp_refused' => '[!`{command}` não foi executado: /{name} é um prompt MCP obtido de um servidor, texto que chegou pela rede. Um corpo obtido recusa formas de shell independentemente da confiança deste projeto — indique a chave do servidor sob "mcpPromptShell" na sua própria configuração de utilizador para que as suas formas de shell sejam julgadas pelo portão de permissões — o resto do prompt foi enviado.]',
    'host.loop.not_configured' => 'Agendamentos não configurados nesta sessão — /loop não tem relógio para funcionar. Uma execução simples de `candy-code` traz sempre um; uma compilação de integração com host deve fornecê-lo.',
    'host.loop.usage' => 'Utilização: /loop <interval> <prompt> — intervalo como 90s, 15m, 2h, 1d (mínimo 10s). O ciclo vive neste processo; /schedules lista-o, /schedules delete termina-o.',
    'host.loop.bad_interval' => 'Não é um intervalo: {interval}. Use segundos (60), ou um sufixo: 90s, 15m, 2h, 1d.',
    'host.loop.registered' => 'Ciclo {name}: a cada {every} — `{prompt}` entra na fila como um turno aqui (primeira execução a um intervalo de distância). Termina com o processo, ou /schedules delete {name}.',
    'host.loop.queued' => "Ciclo '{name}' está na hora: o seu prompt entra na fila desta sessão.",
    'host.output_style.arity' => '/output-style aceita um nome de estilo ou `off`; interpretado como `{args}`.',
    'host.output_style.available' => 'Estilos disponíveis: {names}',
    'host.output_style.cleared' => 'Nenhum estilo de saída está ativo agora — o prompt segue sem manual de regras de estilo a partir do próximo turno.',
    'host.output_style.column_source' => 'Origem',
    'host.output_style.column_state' => 'Estado',
    'host.output_style.column_style' => 'Estilo',
    'host.output_style.empty' => "Nenhum estilo de saída encontrado.\nUm estilo é um ficheiro markdown em ~/.candy-code/styles/ (ou .candy-code/styles/ no projeto),\nnomeado pelo seu nome de ficheiro: terse.md é selecionado com /output-style terse.",
    'host.output_style.footer' => "/output-style <name> seleciona um estilo; exatamente um está ativo de cada vez, e uma\nmudança limpa o anterior. /output-style off limpa a posição. `off` é uma\npalavra reservada — um ficheiro chamado off.md não pode ser selecionado. Um estilo desativado pelo seu\npróprio frontmatter (`enabled: false`) fica fora do prompt independentemente do nome.",
    'host.output_style.heading' => 'Estilos de saída (apenas sessão — nada aqui é gravado na configuração):',
    'host.output_style.matches' => ' (este nome corresponde a {count} ficheiros de estilo — todos ativos)',
    'host.output_style.nothing_active' => 'Nenhum estilo de saída estava ativo — nada para limpar.',
    'host.output_style.self_disabled' => "\nO seu frontmatter indica enabled: false, pelo que fica fora do prompt até essa linha mudar — a seleção não pode sobrepor-se a um ficheiro que se desativou a si próprio.",
    'host.output_style.set' => "Estilo {name}: ATIVO para esta sessão.{note}\nSegue no prompt a partir do próximo turno; um estilo anterior foi removido — exatamente um está ativo.",
    'host.output_style.state_active' => 'ativo',
    'host.output_style.state_off' => 'off',
