    'host.doctor.column_check' => 'Verificação',
    'host.doctor.column_detail' => 'Detalhe',
    'host.schedules.not_configured' => 'Agendamentos não configurados nesta sessão.',
    'host.schedules.usage' => 'Utilização: /schedules [list] | add <name> <interval> <prompt> [--mode <mode>] [--provider <name>] [--heartbeat] | enable <name> | disable <name> | delete <name>. As linhas vivem em ~/.candy-code/schedules.json; /schedules add cria uma através dos limites da fábrica da ferramenta Schedule, /loop regista uma efémera.',
    'host.schedules.none' => 'Sem agendamentos. /schedules add <name> <interval> <prompt> cria um através dos mesmos limites da ferramenta Schedule, ou escreva uma linha em ~/.candy-code/schedules.json (`name`, `every` em segundos, `prompt`, `root` — o diretório do projeto onde dispara; opcionais `provider`, `permissionMode` (grafias bypass-class são recusadas; omita para o piso não interativo), `enabled`, `timeoutSeconds`, `kind` (`task` responde, `heartbeat` pode ficar em silêncio)), ou /loop um para esta sessão. docs/SCHEDULES.md é o formato.',
    'host.schedules.row' => '{state}{kind}{name} — a cada {every}, próximo {next} @ {root}: {prompt}',
