    'host.schedules.added' => 'Agendamento {name}: a cada {every} — `{prompt}` é executado neste projeto como uma execução em segundo plano supervisionada (primeira execução daqui a um intervalo, próxima {next}). Criado pela fábrica da ferramenta Schedule: modo definido na criação, contabilizado no limite de modelos por projeto, vinculado a esta raiz. `/schedules delete {name}` remove-o.',
