    'host.compact.thrash' => 'A compactação de contexto correu {times} vezes seguidas e a transcrição voltou acima do limite de cada vez, pelo que este prompt não foi enviado e não foi tentada mais compactação. As trocas recentes que a reescrita mantém na íntegra são o que não cabe — reduza as maiores (a saída de ferramentas costuma ser o grosso), ou recomece com /rewind ou /clear. /model com uma janela de contexto maior também resolve isto.',
    'host.compact.tier_report' => 'O contexto atingiu o nível de compactação automática, pelo que as trocas mais antigas foram resumidas: {before} mensagens -> {after} mensagens, ~{saved}% da contagem estimada de tokens libertados (~{tokens} tokens estimados agora, contra uma janela de contexto de {limit} tokens).',
    'host.compact.truncated.one' => '{count} mensagem atingiu {tier} sozinha, pelo que foi truncada para caber na janela de contexto em vez de o turno ser recusado: ~{tokens} tokens estimados agora, contra uma janela de contexto de {limit} tokens. O texto enviado ao modelo leva um marcador onde foi cortado; o seu original completo fica na transcrição, oculto ao modelo.',
    'host.compact.truncated.other' => '{count} mensagens atingiram {tier} sozinhas, pelo que foram truncadas para caber na janela de contexto em vez de o turno ser recusado: ~{tokens} tokens estimados agora, contra uma janela de contexto de {limit} tokens. O texto enviado ao modelo leva um marcador onde cada uma foi cortada; os seus originais completos ficam na transcrição, ocultos ao modelo.',
