    // --- fix-tui-interact 2026-10-14 ---
    'tui.picker.notice.slash_filter' => '`{word}` parece um comando de barra, não um filtro — Enter aqui retomaria a melhor correspondência. Prima Escape e escreva o comando na entrada.',
    'tui.app.stop_all_armed' => 'Prestes a parar todos os agentes em execução — prima "s" novamente em 3 s para confirmar.',

    // --- fix-app-launch 2026-10-14 ---
    'appLaunch.doctor.mbstring_missing' => 'em falta — cálculos de largura de quadro (mb_*) não podem ser executados; reinstale o PHP com ext-mbstring',
    'appLaunch.doctor.intl_missing' => 'em falta — cálculos de largura de grapheme/IntlChar não podem ser executados; reinstale o PHP com ext-intl',
    'appLaunch.notice.policy_changed' => '⚠ config.json ou hooks.yaml alteraram-se desde a última execução. Novos hooks de projeto ficam em quarentena apenas para esta execução — reveja ~/.candy-code/config.json e hooks.yaml, depois são aceites',
    'appLaunch.notice.project_policy_changed' => '⚠ O hooks.yaml de um projeto de confiança contém entradas que a última execução nunca viu. Novos hooks de projeto ficam em quarentena apenas para esta execução — reveja o .candy-code/hooks.yaml desse repositório, depois são aceites',
    'appLaunch.notice.bypass_mode' => '⚠ O modo de permissão é bypass-permissions: cada chamada de ferramenta é executada sem confirmação. Altere com /permissions (TUI), --permission-mode, ou defina um modo de permissão diferente em ~/.candy-code/config.json',
    // C-SEC-7.a: `-p` now defaults to the ASKING mode, so an unattended scripted
    // run that named no mode starts refusing — the launch says so once, and names
    // the one-flag fix. No trailing period — STDERR_LINE_FORMAT adds one
    // (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.headless_default' => 'ℹ -p inicia no modo de permissão default: uma execução desatendida recusa cada chamada de ferramenta que pediria confirmação. Passe --permission-mode (bypass-permissions executa tudo) para execuções em script',
    // C-SEC-7.e (owner ruling t212, option 3): the implicit autoReview default
    // announces once per session the first time it engages — de-duped by message
    // identity in the launch-notices store, like the bypass banner. Names the
    // opt-out and owns up to the money. No trailing period — STDERR_LINE_FORMAT
    // adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.auto_review_default' => '⚠ autoReview está ativo por omissão para esta execução: chamadas de modo automático sinalizadas são revistas pelo modelo de título, e cada revisão é uma chamada de modelo paga. Defina autoReview como false em ~/.candy-code/config.json para desativar',
    // C-SEC-6.b: names the file, what it added, and what could not be honoured.
    // No trailing period — STDERR_LINE_FORMAT adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.project_narrowing_rules' => '⚠ {file} restringiu as permissões desta execução: {count} regra(s) de negar/perguntar carregada(s) primeiro, {dropped} regra(s) de permitir descartada(s) — um ficheiro de projeto não pode conceder permitir',
    'appLaunch.notice.restricted' => '⚠ --restricted: esta execução corre sem ferramentas de execução de código — Bash, PtyRun, Task, Workflow, ShellStop e mcp_call estão ausentes de todos os conjuntos voltados para o modelo; as ferramentas de ficheiro mantêm o seu confinamento de caminho e /permissions não pode repor as ferramentas removidas',
    'appLaunch.notice.safe_mode' => '⚠ --safe-mode: raízes de projetos de confiança, bundles, e skills, comandos e agentes externos são todos ignorados para esta execução — comporta-se como se nada tivesse sido alguma vez confiado',

    // --- fix-w2-chat 2026-10-14 ---
    'chat.launch.echo_backend' => 'Nenhum fornecedor está configurado, pelo que esta sessão corre no backend de eco offline integrado — as respostas são ecoadas localmente, nenhum modelo é chamado. Execute `candy-code doctor` para ver o que um fornecedor precisa, depois prima Ctrl+P para mudar de modelo quando um estiver configurado.',
    'keys.chat.repaint' => 'Limpar o ecrã e redesenhar o quadro',
    'keys.unbound' => 'não vinculado',

    // --- C-EXT-1 (Claude Code hook dialect) 2026-10-27 ---
    'hooks.notice.advisory' => '⚠ O hook `async` do Claude Code `{hook}` saiu com {code}. Um hook `async` pede para observar uma chamada de ferramenta em vez de a condicionar, pelo que não tem poder para bloquear uma e a chamada prosseguiu. O que disse: {reason}',
    'hooks.notice.claude_dialect' => '⚠ O hook `{hook}` do Claude Code terminou com {code}, o que o Claude Code interpreta como uma reclamação não bloqueante em vez de uma decisão, pelo que a chamada de ferramenta prosseguiu. O que disse: {reason}',
    'hooks.notice.said_nothing' => '(nada em stderr)',
    'hooks.notice.system_message' => '⚠ O hook `{hook}` deixou-lhe uma mensagem: {message}',

    // --- C-EXT-6.c (type: http hooks) 2026-10-30 ---
    // Every row names the hook and scheme://host only: never a path, a query,
    // or any header value, so an Authorization cannot ride out of the process
    // inside its own refusal.
    'hooks.http.deny_bad_url' => 'O hook HTTP `{hook}` está configurado com um URL que não pode ser utilizado ({reason}); o destino apresentado é {target}. Um hook que não consegue indicar para onde vai não aprovou esta chamada.',
    'hooks.http.deny_scheme' => 'O hook HTTP `{hook}` referencia {target}, que não é um URL http ou https. candy-code só liga hooks através desses dois esquemas, e a chamada é recusada em vez de ser executada sobre um transporte não verificado.',
    'hooks.http.deny_credentials' => 'A hook HTTP `{hook}` transporta credenciais no seu URL ({target}). Uma palavra-passe escrita num URL acaba por aparecer em registos e proxies, pelo que é recusada aqui; envie-a como um cabeçalho cujo valor leia um nome de `allowedEnvVars` em alternativa.',
    'hooks.http.deny_blocked_target' => 'O hook HTTP `{hook}` não pode ser consultado: {reason} ({target}). Os endereços privados e link-local são recusados pela mesma regra que uma requisição externa, e uma proteção que nunca foi alcançada não aprovou esta chamada.',
    'hooks.http.deny_unanswered' => 'O hook HTTP `{hook}` não respondeu ({reason}); o destino era {target}. Um hook que não pôde ser alcançado não aprovou esta chamada, pelo que é recusada.',
    'hooks.http.deny_header_injection' => 'O hook HTTP `{hook}` não pode enviar o cabeçalho `{field}`: o nome ou o respetivo valor contém um carácter de controlo, que é enquadramento do pedido e não um valor de cabeçalho. Nada foi enviado para {target} e a chamada é recusada.',
    'hooks.http.notice_unanswered' => '⚠ O hook HTTP `{hook}` não respondeu ({reason}), pelo que não foi possível condicionar a chamada. Foi consultado em {target}.',
    'hooks.http.reason_unreachable' => 'a ligação ou o pedido excederam o tempo limite dentro do próprio tempo limite do hook',
    'hooks.http.reason_oversized' => 'a resposta excedeu {bytes} bytes e não terminou em lado nenhum',
    'hooks.http.reason_no_status' => 'a resposta não continha linha de estado HTTP',
    'hooks.http.reason_redirect' => 'foi redirecionado e uma chamada de hook não segue redirecionamentos',
    'hooks.http.reason_status' => 'a resposta não foi um estado 2xx',


    // --- C-EXT-6.d (type: prompt hooks) 2026-10-31 ---
    // Nothing was dialled and nothing was spent when these fire, so no row
    // carries a {target}: the hook either has no backend to be asked on, or
    // the answer it got is not a verdict.
    'hooks.prompt.deny_unanswered' => 'O hook de prompt `{hook}` não respondeu ({reason}). Um hook cujo veredicto nunca foi devolvido não aprovou esta chamada, pelo que é recusado.',
    'hooks.prompt.notice_unanswered' => '⚠ O hook de prompt `{hook}` não respondeu ({reason}), pelo que não pôde controlar a chamada.',
    'hooks.prompt.reason_call_failed' => 'não foi possível consultar o modelo',
    'hooks.prompt.reason_empty_verdict' => 'O prompt hook `{hook}` negou esta chamada sem indicar um motivo.',
    'hooks.prompt.reason_no_backend' => 'esta execução não tem um backend de títulos para lhe pedir',
    'hooks.prompt.reason_no_prompt' => 'a entrada contém um prompt vazio para perguntar',
    'hooks.prompt.reason_unparseable' => 'a sua resposta não foi o único objeto JSON com um `ok` booleano com que é obrigatório responder',

    // --- settings help (W3-B i18n migration) ---
    'settings.advisorModel.help' => 'Modelo que a ferramenta `Advisor` consulta para uma segunda opinião; não definido — o predefinido — não disponibiliza a ferramenta de todo (não existe alternativa de modelo económico: o objetivo é um modelo que escolheu).',
    'settings.allowedTools.help' => 'Lista branca de nomes de ferramentas ou globs; sem definição, oferece todas as ferramentas.',
    'settings.attribution.help' => '{"commit": "…", "pr": "…"}: o trailer e a linha de PR que as orientações do git pedem.',
    'settings.autoCommit.help' => 'off, turn (um commit por turno, mensagem do modelo de título) ou edit (um por Write/Edit); /undo reverte-o.',
    // C-SEC-7.e (owner ruling t212, option 3): the help states the implicit
    // default, the once-per-session announce, and the paid-call fact.
    'settings.autoReview.help' => 'Em modo auto, uma chamada sinalizada pelo classificador de segurança (exceto uma constatação de segurança, que pergunta sempre) é revista pelo modelo de título, que a permite, lhe pergunta ou a nega. Ativo por omissão sempre que existe um modelo analisável, e um arranque que ativa essa predefinição informa-o uma vez; defina false para desativar. Cada revisão é uma chamada paga a um modelo.',
    'settings.autoReviewModel.help' => 'O `provider/model` no qual o revisor automático é executado, por exemplo, `openai/gpt-4.1-mini`; vazio significa o modelo do título. Um provider que não pode ser criado desativa o revisor com um aviso de arranque.',
    'settings.autoReviewScope.help' => 'O que o `autoReview` envia ao revisor: `shell` (predefinição) é todo o comando de shell não só de leitura que a lista de padrões passou; `writes` revê também `Edit`, `Write`, `ApplyPatch` e `WebFetch`, com o diff pendente para as ferramentas de escrita; `all` revê todas as chamadas que a lista passou. Qualquer outra grafia comporta-se como `shell`. Cada revisão é uma chamada paga ao modelo.',
    'settings.autoTest.help' => 'Após um turno que editou um ficheiro, execute `testCommand`; em caso de falha, o resultado é devolvido ao modelo, no máximo 3 vezes por turno.',
    'settings.bashInteractiveIdleSeconds.help' => 'Segundos que uma execução Bash `interactive: true` pode não imprimir nada antes de ser interrompida por espera de uma tecla.',
    'settings.bashMaxTimeoutSeconds.help' => 'O maior `timeout` que um comando Bash pode solicitar; valores superiores são limitados a ele.',
    'settings.bashSandbox.help' => 'O Linux executa o Bash dentro do bubblewrap; o macOS executa-o dentro de um perfil Seatbelt via `sandbox-exec` — com escrita apenas na raiz de trabalho (`no-network` também corta a rede). `allowlist` (Linux) encaminha o tráfego de saída pela proxy de saída do arranque, que concede apenas os hosts listados em `sandboxAllowedDomains`: com a lista vazia predefinida, comporta-se EXATAMENTE como `no-network` até que liste hosts, e mesmo depois de listados, o tráfego não-HTTP (ssh, portas de bases de dados) e qualquer host não listado falham. No macOS, `allowlist` é aplicado como `no-network`. Recusa comandos quando a jail não pode iniciar; um valor não reconhecido significa `no-network`, nunca `off`.',
    'settings.bashSandboxNestedUserns.help' => 'Defina como `true` para permitir que um comando `Bash` em sandbox crie o seu próprio namespace de utilizador, o que é necessário para o podman ou buildah sem root e para uma sandbox do Chromium. O valor predefinido `false` executa o bubblewrap com `--unshare-user --disable-userns`, bloqueando a via habitual de saída de uma jaula de montagem; num host cujo bubblewrap é demasiado antigo para essas flags, a jaula executa o conjunto simples e a sua própria descrição indica-o.',
    'settings.bashTimeoutSeconds.help' => 'Segundos que um comando Bash pode executar quando o modelo não fornece `timeout`; nunca acima do limite máximo Bash.',
    'settings.chatToolTimeoutSeconds.help' => 'Orçamento de tempo real de um lote de chamadas de ferramentas que o caminho nativo de chat (fornecedor `command`) bifurca; os retardatários são terminados.',
    'settings.claudeMcpArgs.help' => 'Argumentos para esse binário; não definido usa a predefinição do transporte.',
    'settings.claudeMcpBinary.help' => 'Caminho absoluto do binário `claude` que o transporte claude-mcp pode iniciar.',
    'settings.claudeMcpEnv.help' => 'Variáveis de ambiente literais passadas a esse binário.',
    'settings.compaction.autoPercent.help' => 'Percentagem da janela a partir da qual as interações mais antigas são condensadas automaticamente antes de o prompt ser enviado.',
    'settings.compaction.autoTokens.help' => 'Limite absoluto do nível automático e do orçamento de passos por turno. 0 desativa o limite.',
    'settings.compaction.blockPercent.help' => 'Quota da janela além da qual o prompt é recusado até que o espaço seja libertado; o único nível que recusa.',
    'settings.compaction.blockTokens.help' => 'Limite absoluto do nível de bloqueio; não definido por omissão. Defini-lo permite que um limite recuse pedidos.',
    'settings.compaction.idleAuto.help' => 'Compactar uma sessão ociosa acima do tier durante a inatividade, em vez de esperar pelo próximo prompt, utilizando a mecânica do tier automático (aplicam-se o limite de gasto e o travão de thrashing). off: nunca; hour: após a janela completa de compaction.idleOfferSeconds; cacheTtl: pouco antes da expiração do prompt-cache do fornecedor — uma hora quando o fornecedor marca cache breakpoints, cerca de 5 min para caches do lado do servidor, nunca quando reporta nada em cache — uma vez que o histórico está acima de um limite inferior ao tier automático, porque o próximo prompt pré-preencheria toda a conversa sem cache; no tick de 60 segundos, um cache de 5 min dobra a cerca de 4 minutos de inatividade. Custa uma chamada em segundo plano ao fornecedor; requer compaction.idleOfferSeconds acima de 0. Um bool continua a ser lido: true significa hour, false significa off.',
    'settings.compaction.idleOfferSeconds.help' => 'A sessão que ultrapassou toda a janela de contexto e ficou inativa tanto tempo recebe /compact em vez de enviar o prompt. 0 nunca oferece.',
    'settings.compaction.keepRecent.help' => 'Interações utilizador/assistente mais recentes que uma compactação mantém na íntegra.',
    'settings.compaction.mode.help' => 'llm: o modelo de resumo escreve os resumos (a heurística é o seu fallback); heuristic: resumos locais de uma linha, nunca uma chamada ao modelo; off: nada se compacta sozinho, /compact continua a funcionar e a camada de bloqueio continua a recusar.',
    'settings.compaction.modelTokenCaps.help' => '"<model>" ou "<provider>/<model>": {"reminderTokens", "autoTokens", "blockTokens"}} que substitui os três limites; 0 limpa um.',
    'settings.compaction.refillLimit.help' => 'Compações automáticas consecutivas que podem voltar diretamente acima do respetivo nível, prompt não enviado, antes de o próximo prompt ser recusado em vez de compactado novamente.',
    'settings.compaction.reminderPercent.help' => 'Proporção da janela a partir da qual o lembrete "considerar compactação" e o resumo em segundo plano antecipado começam; abaixo do escalão automático.',
    'settings.compaction.reminderTokens.help' => 'Limite absoluto do escalão de lembrete: dispara em min(percentage, this). 0 desativa o limite.',
    'settings.compaction.summaryAssistantChars.help' => 'Respostas do assistente mais longas do que isto tornam-se "[exchanged information]" numa linha de resumo heurística.',
    'settings.compaction.summaryUserChars.help' => 'Caracteres de uma mensagem de utilizador que a linha de resumo heurística mantém.',
    'settings.compaction.toolOutputChars.help' => 'Caracteres da metade do assistente numa troca condensada que o modelo de resumo apresenta.',
    'settings.connectTimeoutSeconds.help' => 'Limite para atingir um host do fornecedor (DNS, TCP, TLS); não é um timeout de pedido.',
    'settings.contextPruning.compress.help' => 'manual oferece Compress apenas num turno iniciado com /compress, uma chamada; auto oferece-o em todos os turnos em que o modelo pode fazer poda.',
    'settings.contextPruning.iterationNudgeThreshold.help' => 'Resultados das ferramentas desde o último prompt, após o qual um ciclo longo de ferramentas é lembrado de podar.',
    'settings.contextPruning.maxContextTokens.help' => 'Tamanho do contexto acima do qual a linha mais recente contém o lembrete "prune now" mais forte.',
    'settings.contextPruning.minContextTokens.help' => 'Tamanho do contexto abaixo do qual o modelo nunca é alertado para purgar; não deve exceder o tamanho do alerta rígido.',
    'settings.contextPruning.mode.help' => 'auto elimina linhas substituídas no início de cada turno; manual apenas em /sweep; off não mostra tags de referência. /pruning sobrepõe-se por sessão.',
    'settings.contextPruning.nudgeFrequency.help' => 'Novas linhas que um lembrete espera após a última, para não se repetir em cada passo.',
    'settings.contextWindow.help' => 'Sobrescrita da janela de tokens: um número para o modelo do fornecedor, ou {"<model>": tokens}.',
    'settings.debug.commands.help' => 'Apresente no stderr cada diretório ou ficheiro de comando personalizado recusado, e não apenas a contagem de uma linha do arranque.',
    'settings.debug.rules.help' => 'Imprimir cada diretório ou ficheiro de regras recusado em stderr.',
    'settings.debug.skills.help' => 'Apresente cada ficheiro de skill ignorado e diretório de skills recusado em stderr, não apenas a contagem de uma linha do arranque.',
    'settings.debug.stream.help' => 'Coloque a linha "onToken observer threw, detaching it" em stderr quando o sink de streaming de um embedder falha a meio de um turno.',
    'settings.diffPreviewRows.help' => 'Linhas de um diff de Edit ou Write mostradas na transcrição antes de o resto ser resumido.',
    'settings.diffStyle.help' => 'Disposição do diff no transcript: `auto` apresenta os hunks lado a lado em terminais largos (120 colunas ou mais) e unificados noutros casos, `unified` sempre numa coluna, `split` sempre em duas. Os corpos do diff são coloridos por token em qualquer disposição; a coluna de marcadores `+`/`-` mantém a sua cor.',
    'settings.disabledMcpServers.help' => 'Nomes de servidores ou padrões glob (`untrusted_*`) do `.mcp.json` que nunca são iniciados, listados nem chamados, para o agente principal e cada subagente.',
    'settings.disabledRules.help' => 'Pacotes de regras ao nível do utilizador excluídos do prompt desde o primeiro turno.',
    'settings.disabledSkills.help' => 'Skills removidas da descoberta; também prevalecem sobre enabledSkills.',
    'settings.disabledTools.help' => 'Nomes de ferramentas ou globs removidos do conjunto de ferramentas exposto ao modelo.',
    'settings.doubleEscSeconds.help' => 'Em quanto tempo o segundo Esc deve seguir o primeiro para cancelar uma execução em curso.',
    'settings.embeddingModel.help' => 'Modelo de embedding para a recuperação de memória por turno; sem definição, classifica notas apenas por palavra-chave.',
    'settings.enabledSkills.help' => 'Competências com corpo completo no prompt do sistema em cada turno.',
    'settings.env.diffMaxBytes.help' => 'Bytes que cada uma das duas secções de git diff mantém antes de ser truncada com uma nota.',
    'settings.env.gitDiffAfterWrites.help' => 'Depois de um passo que escreveu ficheiros, mostrar os diffs do git preparados e não preparados no contexto do turno.',
    'settings.expandToolOutput.help' => 'Mostrar na íntegra a saída de cada chamada de ferramenta concluída na transcrição; Ctrl+O ou um clique continua a recolher uma.',
    'settings.extraBody.help' => 'Campos de nível superior do pedido adicionados a cada pedido ao fornecedor `custom`.',
    'settings.formatCommands.help' => 'Comando de formatação pós-edição por extensão de ficheiro ({"php": "vendor/bin/php-cs-fixer fix {file}"}); executa-se antes do lint pós-edição e reescreve o ficheiro. Desativado por omissão.',
    'settings.formatAuto.help' => 'Permitir que a tabela de extensões integrada (gofmt, rustfmt, ruff/black, shfmt, terraform fmt, o prettier do node_modules do próprio projeto) formate um ficheiro editado quando `formatCommands` não indicar um comando para a sua extensão. As entradas explícitas têm prioridade; um projeto ainda precisa de `trustedProjectHooks`. Desativado por omissão.',
    'settings.globMaxMatches.help' => 'Caminhos que um Glob recolhe antes de o seu percurso terminar; o limite de saída ainda restringe o resultado.',
    'settings.grepTimeoutSeconds.help' => 'Segundos que uma pesquisa Grep pode executar antes de ser terminada; as correspondências encontradas até ao limite são devolvidas como resultado parcial.',
    'settings.hooksDefaultTimeoutSeconds.help' => 'Segundos que uma entrada de hook sem `timeout:` pode correr antes de ser terminada e contada como recusa.',
    'settings.includeGitInstructions.help' => 'Se a orientação genérica de commit da ferramenta Bash está incluída no prompt do sistema.',
    'settings.instructions.help' => 'Globs de ficheiros cujo conteúdo se torna texto autoritativo do prompt de sistema.',
    'settings.instructions.walkToRoot.help' => 'Ativação opcional: ler também ficheiros de instruções acima do marcador .git mais próximo, até, mas sem incluir, o diretório pessoal. Apenas ao nível do utilizador; cada leitura mantém o seu limite de contenção e de tamanho.',
    'settings.instructionsExclude.help' => 'Globs de ficheiros de instruções a ignorar, registados como recusas; apenas ao nível do utilizador — um repositório não pode silenciar o seu operador. Ficheiros dentro do checkout correspondem por caminho relativo ao checkout; ficheiros ancestrais e forçados fora dele correspondem por caminho absoluto, pelo que `**/CLAUDE.local.md` atinge também as cópias ancestrais.',
    'settings.keybindings.help' => '{"shell.palette": "Ctrl+B"}: associar um acorde EXTRA a um id de associação (a referência /keys dá-lhes nome) — Ctrl+<key>, Alt+<key>, Shift+<key>, ou uma tecla de função isolada; o acorde predefinido continua a funcionar. Presente-mas-inutilizável recusa o arranque; remova a tecla para as associações predefinidas.',
    'settings.layout.help' => 'O manifesto do painel acoplado; escrito pela shell quando os painéis se movem.',
    'settings.lintCommands.help' => 'Comando de lint pós-edição por extensão de ficheiro ({"php": "…", "js": false}); `php -l` está integrado.',
    'settings.lsp.help' => '{"php": {"command": "intelephense", "args": ["--stdio"]}}: servidores para diagnósticos pós-edição, esquemas do Read e a ferramenta Lsp.',
    'settings.lspAutoDetect.help' => 'Iniciar o servidor de linguagem indicado pela impressão digital do projeto (composer.json → intelephense, package.json + tsconfig.json → typescript-language-server, pyproject.toml ou setup.py → pyright-langserver, go.mod → gopls, Cargo.toml → rust-analyzer) quando o respetivo binário está no PATH; entradas `lsp` manuais têm prioridade por linguagem. Iniciar um servidor executa esse servidor e o código de compilação na árvore aberta, pelo que as impressões digitais iniciam servidores apenas em projetos de que confia para hooks; uma raiz não confiável não inicia nenhum e regista a omissão nas notificações de arranque.',
    'settings.maxCheckpoints.help' => 'Pontos de verificação de turno a que /rewind pode regressar, por sessão; os mais antigos são eliminados após este limite.',
    'settings.maxCostUsd.help' => 'Recusar novas interações quando a despesa reportada pelo fornecedor de uma execução atingir este montante em dólares; não definido significa sem limite. /budget altera-o apenas para a execução em curso.',
    'settings.maxOutputTokens.help' => 'Limite máximo de saída por pedido; sem definição não envia substituição e aplica-se o valor predefinido do fornecedor.',
    'settings.maxToolSteps.help' => 'Chamadas ao fornecedor permitidas por turno; não definido mantém o valor predefinido do motor.',
    'settings.mcp.enabled.help' => 'Inicia os servidores MCP indicados no .mcp.json de um projeto de confiança; off não inicia nenhum e as interfaces reportam o arranque como desativado.',
    'settings.mcp.lazySchemaTokens.help' => 'Tokens de esquema que um servidor MCP pode anunciar antes de as suas ferramentas remeterem para mcp_list/mcp_call; 0 nunca remete.',
    'settings.mcpResultCapBytes.help' => 'Máximo de bytes que a resposta de uma ferramenta MCP pode passar ao modelo.',
    'settings.memory.autoConsolidate.help' => 'Guardar factos duradouros de turnos concluídos na memória e fundir o registo de compactação nela (a passagem de sonho); cada uma é uma chamada faturada.',
    'settings.memory.dreamIntervalSeconds.help' => 'Tempo mínimo entre duas passagens de sonho para um projeto; cada passagem é um turno faturado, só de leitura.',
    'settings.memory.dreamProposeSkills.help' => 'Deixe o dream pass propor competências como rascunhos em ~/.candy-code/skills-proposed; nenhuma fica ativa até que execute /skills accept.',
    'settings.memory.entryMaxBytes.help' => 'A linha de índice da nota mais longa pode aparecer antes de ser mostrada truncada; reduzida ao limite de notas do utilizador se o exceder.',
    'settings.memory.projectNoteMaxBytes.help' => 'A maior nota de memória de um projeto pode ser quando é escrita em .candy-code/memory/ do repositório.',
    'settings.memory.promptMaxBytes.help' => 'Orçamento de bytes para as linhas de notas do índice de memória; o orçamento de notas do utilizador é reduzido para caber nele.',
    'settings.memory.promptMaxEntries.help' => 'A maioria das notas listadas pelo índice de memória do prompt, mais recentes primeiro; as notas do utilizador contam-se nele.',
    'settings.memory.userMaxBytes.help' => 'Orçamento de bytes para as linhas de âmbito do utilizador, dentro do orçamento total.',
    'settings.memory.userMaxEntries.help' => 'A maioria das suas notas interprojetos (âmbito do utilizador) é listada primeiro, na contagem de notas.',
    'settings.modelPrices.help' => 'USD por 1M de tokens por modelo ({"input": …, "output": …}), para o total de gastos e limite.',
    'settings.models.help' => 'O modelo a executar, por fornecedor ({"<provider>": "<model id>"}); se não definido, usa o predefinido do fornecedor.',
    'settings.mouse.help' => 'Reportar o rato ao candy-code (cliques, roda, seleção); desativado devolve ao terminal o seu próprio copy-on-select.',
    'settings.mouseClicks.help' => 'Clicar e arrastar atuam sobre o que atingem; desativado mantém a roda e ignora cliques.',
    'settings.notices.transcriptLimit.help' => 'A maioria dos avisos de arranque é apresentada como linhas da transcrição; os restantes são contados numa linha "e mais N", e o stderr contém-nos todos.',
    'settings.notify.help' => 'off, bell (BEL) ou osc9 (uma notificação do ambiente de trabalho): enviada quando um turno termina e quando o agente aguarda uma aprovação.',
    'settings.paletteMru.help' => 'Quantas linhas da paleta utilizadas recentemente são memorizadas e classificadas primeiro; 0 não memoriza nenhuma.',
    'settings.parallelToolCalls.help' => 'Executar em simultâneo as chamadas de ferramentas só de leitura de um turno.',
    'settings.parallelToolDeadlineSeconds.help' => 'Teto de tempo real para um lote de chamadas de ferramentas despachadas em simultâneo.',
    'settings.permissionMode.help' => 'Como as chamadas de ferramentas são controladas. Nunca obtido de um ficheiro de projeto.',
    'settings.permissionRules.help' => 'Regras ordenadas de permitir / negar / perguntar, avaliadas em cada chamada de ferramenta. O settings.json partilhado de um projeto de confiança pode adicionar entradas de negar / perguntar — apenas a restringir.',
    'settings.permissions.autoAllowReadOnly.help' => 'Em modo default e accept-edits, executar uma linha Bash composta apenas por comandos de leitura (ls, cat, grep, git log, …; sem redirecionamento de ficheiros, sem substituição, cd apenas dentro do projeto) sem perguntar. Um projeto só pode desativá-lo.',
    'settings.permissions.autoStrikeLimit.help' => 'No modo auto, este número de chamadas bloqueadas consecutivas de uma categoria transforma a seguinte numa pergunta.',
    'settings.permissions.autoTotalLimit.help' => 'Em modo auto, depois de este número de chamadas ter sido bloqueado numa sessão, cada bloqueio adicional pergunta-lhe em vez disso.',
    'settings.pluginPaths.help' => 'Diretórios adicionais percorridos para pacotes de plugins em formato Claude, além das duas raízes instaladas; um valor pode designar um pacote em si ou um contentor de pacotes. Apenas ao nível de utilizador — um checkout não pode inscrever os seus próprios plugins.',
    'settings.promptCache.keepWarm.help' => 'Pings de aquecimento permitidos por período de inatividade; 0 (predefinição) desativa. Cada ping reenvia o prefixo congelado de uma sessão inativa com uma linha de instrução que pede uma resposta de um carácter, para que o fornecedor atualize a sua cache de prompt antes de o TTL expirar e o próximo prompt não pré-preencha toda a conversa sem cache. Dispara apenas onde o fold de cacheTtl desceu — abaixo do seu mínimo ou antes da sua hora — no mesmo tick/alarme em que a vigilância do fold já corre, nunca a meio de um turno, nunca mais de um de cada vez, nunca além desta contagem por período. São chamadas faturadas para uma sessão que ninguém está a observar; o limite de gastos continua a aplicar-se. A contagem aparece em /usage sob `warm`.',
    'settings.promptCache.help' => 'Se os provedores `vertex` e `bedrock` marcam pontos de quebra do cache de prompt.',
    'settings.promptSuggestionHistory.help' => 'Mensagens recentes (cada uma limitada a 2000 caracteres) apresentadas na chamada de sugestão de prompt.',
    'settings.promptSuggestions.help' => 'Após cada turno, pedir ao modelo de título a mensagem que provavelmente vai enviar a seguir e mostrá-la esbatida no campo de entrada vazio (→ aceita-a).',
    'settings.provider.help' => 'Fornecedor de LLM com que a sessão comunica; cada prompt é enviado para o respetivo host.',
    'settings.providerRetryAttempts.help' => 'Chamadas por pedido ao fornecedor em caso de falha transitória (rede, 5xx, 408, 429), incluindo a primeira; 1 nunca repete.',
    'settings.providerRetryBaseBackoffMs.help' => 'Espera antes da primeira nova tentativa de uma chamada de fornecedor falhada; cada espera seguinte duplica.',
    'settings.providers.help' => 'Definições de fornecedores por nome ({"<name>": {"type": …, "baseUrl": …, "apiKey": …, "model": …}}); cada entrada sobrepõe-se aos valores predefinidos desse tipo. Apenas nível de utilizador: um projeto nunca deve alterar o destino para onde a sua credencial é enviada.',
    'settings.queueMode.help' => 'steer (o agente lê-a no próximo passo), followup (enviado após o turno) ou interrupt (interrompe o turno no próximo passo e envia). Tab enfileira sempre.',
    'settings.readMaxBytes.help' => 'Limite máximo de uma chamada Read; a página abaixo mostra o tamanho que uma leitura costuma devolver.',
    'settings.readPageBytes.help' => 'Bytes que uma página de leitura pode conter, incluindo números de linha, o que `limit` determinar.',
    'settings.readPageLines.help' => 'Linhas que uma Read devolve quando a chamada não especifica `limit`.',
    'settings.reasoningEffort.help' => 'Nível de raciocínio enviado onde o par o determina: openai (série o e gpt-5, não as versões -chat), anthropic e vertex (claude-3-7 e mais recentes; vertex responde em ambos os seus ramos, claude e gemini), gemini (2.5 e mais recentes), sglang (encaminhado em cada pedido), bedrock (ids claude, como orçamento de raciocínio), codex e claude-code (níveis nomeados encaminhados para a CLI); não definido ou não reconhecido não solicita nada. `/effort` define-o e limpa-o.',
    'settings.redactToolOutput.help' => 'Desativado por omissão: o resultado consolidado da ferramenta é guardado no histórico e em sessions.db exatamente como foi devolvido. Quando ativado, cada resultado da ferramenta passa pelo mesmo redator que protege a memória e `/share`, uma vez consolidado — as credenciais reconhecidas tornam-se `[REDACTED]` nos bytes que persistem e no que os turnos seguintes reproduzem ao modelo (a ferramenta em si continua a executar-se sem alterações). Os campos de imagem, documento e utilização passam sem alterações. `/export` não aplica redação própria: apresenta exatamente o que foi guardado, pelo que tudo o que foi guardado antes de ativar esta opção permanece em bruto.',
    'settings.references.help' => 'Uma lista de diretórios `[{"path": "…", "name": "…"}]` fora do espaço de trabalho que Read, Grep, Glob e Ls também podem abrir, só de leitura; cada um é divulgado no bloco `<env>` com um mapa limitado do que lá reside. A jaula do espaço de trabalho mantém-se inalterada para Write, Edit e Bash — uma referência nunca alarga o que pode ser escrito. Apenas ao nível de utilizador: um repositório com checkout não pode adicionar uma raiz de leitura. Um caminho inexistente, que não seja um diretório, ou que se encontre dentro da raiz da sessão, é recusado no arranque com um aviso.',
    'settings.repoMap.enabled.help' => 'Coloque o mapa de onde o código reside (pacotes e diretórios de origem PSR-4) no prompt do sistema.',
    'settings.repoMap.maxBytes.help' => 'Limite de bytes para cada uma das duas secções do mapa do repositório; as entradas que excedam o limite são contadas, não listadas.',
    'settings.requireReadBeforeWrite.help' => 'Ativado: `Edit`, um `Write` que sobrescreve um ficheiro existente e uma secção `ApplyPatch` que altera, move ou elimina um ficheiro são todos recusados até que o modelo tenha lido esse ficheiro nesta sessão; a criação de ficheiros novos nunca é bloqueada. Desativado por omissão: os ficheiros que o modelo leu continuam protegidos pela regra de alteração em disco de qualquer forma.',
    'settings.resumeCostWarnUsd.help' => 'Após uma retoma desatualizada, o primeiro pedido é retido uma vez quando o reenvio do histórico é estimado em pelo menos este número de dólares sem cache; prima Enter novamente para enviar de qualquer forma, ou execute /compact primeiro. 0 desativa a retenção.',
    'settings.sandboxAllowedDomains.help' => 'Os hosts a que a jail `allowlist` pode aceder: nomes simples (`example.com`), wildcards `*.example.com` e formas `host:port` (predefinição: nada). Usado apenas quando `bashSandbox` é `allowlist` em Linux; com uma lista VAZIA, `allowlist` comporta-se EXATAMENTE como `no-network`. O proxy de saída concede apenas HTTP(S) — cada host não listado recebe 403, e o tráfego não-HTTP (ssh, portas de base de dados) falha. Uma entrada malformada é IGNORADA na aplicação: um erro tipográfico só pode reduzir a concessão, nunca alargá-la. Apenas nível de utilizador: um repositório obtido não pode abrir uma brecha na jail em que chegou. macOS aplica `allowlist` como `no-network` — o ramo de porta loopback é uma melhoria registada.',
    'settings.sandboxScope.help' => 'Quais comandos fora do caminho da ferramenta entram na jail `bashSandbox`: `hooks`, `lint`, `format`, `test`, `lsp`, `mcp` (predefinição: nenhum). Ativo apenas enquanto `bashSandbox` não é `off` — a lista indica quem partilha a jail, nunca se existe uma. Uma entrada não reconhecida lê-se como TODOS os âmbitos (mais restritivo, como um valor `bashSandbox` não reconhecido), e a auditoria de definições identifica-a. Uma jail que não consegue iniciar recusa o trabalho em vez de o executar livremente: hooks de script negam; lint, format e test são ignorados com o motivo; e um servidor LSP ou MCP stdio na jail não é iniciado. Entradas `lsp` e entradas MCP de nível de utilizador têm uma exclusão por servidor `"sandbox": false`; exclusões MCP de nível de projeto são ignoradas.',
    'settings.screenReader.help' => 'Apresentação para utilizadores de leitor de ecrã. Ativado, a aplicação elimina a decoração que um leitor não pode narrar — o indicador de agente fixa-se num quadro estático, e molduras de desenho de caixas, seleção de menu apenas em vídeo invertido e semelhantes dão lugar a texto simples e a um sinal audível, à medida que cada superfície respeita a opção. Desativado é o terminal pintado como habitualmente. A sua própria definição de acessibilidade, como o modo vim da caixa de rascunho: um projeto obtido não a pode alterar. Aplica-se na próxima leitura após guardar — em tempo real, sem recarregar.',
    'settings.rules.standingMaxBytes.help' => 'Orçamento em bytes, enquadrado e escapado, para os ficheiros de regras incorporados por inteiro em cada prompt; uma regra que o exceda é designada por uma linha de ponteiro.',
    'settings.scrollWheelLines.help' => 'Linhas de transcrição que um clique da roda percorre.',
    'settings.sd.apiKey.help' => 'Chave Bearer enviada ao servidor Stable Diffusion, se este a exigir; prefira a forma de marcador de posição `${VAR}` a um literal.',
    'settings.sd.baseUrl.help' => 'URL base HTTP de um webui Stable Diffusion compatível com AUTOMATIC1111 (`http://127.0.0.1:7860`); prompts, imagens e a chave de API saem todos por aí.',
    'settings.sd.defaultModel.help' => 'ID de modelo com que os pedidos de geração começam; o servidor mantém a escolha para si quando não definido.',
    'settings.sd.presets.help' => 'Conjuntos de parâmetros nomeados que o formulário de media oferece; a forma é própria do pipeline de media, opaca à camada de definições.',
    'settings.sd.savePattern.help' => 'Modelo de nome de ficheiro para media guardada; os tokens `[date]`, `[time]`, `[seed]` e `[number]` preenchem-se no momento de guardar.',
    'settings.sd.timeoutSeconds.help' => 'Segundos que um pedido de geração pode executar antes de ser abandonado; a difusão numa GPU fraca demora rotineiramente minutos.',
    'settings.secretEnvAllowlist.help' => 'Nomes de variáveis com forma de credencial (ou globs) que Bash, Grep e hooks de script ainda herdam.',
    'settings.server.allowBypass.help' => 'Se as sessões do servidor podem executar em bypass-permissions ou dont-ask (igual a --allow-bypass).',
    'settings.server.allowedHosts.help' => 'Nomes de host (ou host:port) a que o servidor responde, além dos nomes de loopback e dos seus próprios endereços, p. ex. de um proxy reverso.',
    'settings.server.allowedIps.help' => 'IPs de cliente ou intervalos CIDR autorizados a ligar-se, além de loopback; qualquer outro é recusado com 403 antes do início de sessão. Vazio: sem filtro de endereço.',
    'settings.server.allowedOrigins.help' => 'Origens de navegador adicionais (http(s)://host[:port]) que o servidor aceita, além das suas.',
    'settings.server.askTimeoutSeconds.help' => 'Segundos que uma pergunta de permissão espera por um cliente antes de ser recusada; 0 espera indefinidamente.',
    'settings.server.browseRoot.help' => 'O diretório a que server.dirBrowse está confinado (igual a --browse-root); não definido é o seu diretório pessoal.',
    'settings.server.dirBrowse.help' => 'Permitir que clientes com sessão iniciada listem nomes de diretórios sob server.browseRoot e iniciem sessões aí (igual a --allow-dir-browse). Desativado por predefinição.',
    'settings.server.clientTools.help' => 'Permitir que clientes com âmbito Write registrem ferramentas via tools.client.register para que o modelo possa chamar código que executa no próprio cliente (ferramentas client__*). Desativado por predefinição.',
    'settings.server.drainSeconds.help' => 'Segundos que um servidor em paragem espera por turnos em execução antes de os cancelar; 0 para imediatamente.',
    'settings.server.host.help' => 'O endereço a que `serve` se liga. Qualquer coisa além de loopback também exige --allow-remote no arranque.',
    'settings.server.maxConcurrentTurns.help' => 'Turnos que um servidor executa simultaneamente nas suas sessões; mais um é recusado por ocupado (repetível).',
    'settings.server.maxOpenSessions.help' => 'Sessões que um servidor mantém abertas simultaneamente; além disso, a sessão ociosa menos recentemente utilizada é libertada.',
    'settings.server.port.help' => 'A porta a que `serve` se liga; 0 escolhe uma livre.',
    'settings.server.trustedProxies.help' => 'IPs ou CIDRs cujos X-Forwarded-For / X-Forwarded-Proto o servidor aceita como válidos.',
    'settings.serviceTier.help' => 'Via premium enviada onde o par a define: openai pede `service_tier: "priority"` em ambos os ramos Chat e Responses; anthropic pede `speed: "fast"` (apenas a família claude-opus-5-5 GA e as famílias claude-opus-5 / claude-opus-4-8 research-preview, cujo cabeçalho beta obrigatório viaja automaticamente); não definido ou não reconhecido não pede nada. O modo rápido fatura um prémio que nenhuma tabela de preços por modelo pode derivar: enquanto um par com nível está ativo, os seus turnos registam-se no livro como sem preço, nunca como uma taxa estimada. Aplica-se no arranque e em cada reconstrução de fornecedor ou modelo.',
    'settings.sessionRetentionDays.help' => 'Cada arranque elimina sessões sem nome e sem fixação não tocadas durante este número de dias e indica quais; 0 (a predefinição) mantém tudo.',
    'settings.sessions.autoTitle.help' => 'Dar nome a cada nova sessão a partir do seu primeiro turno com uma chamada ao modelo de título; desativado deixa-a sem nome até /rename.',
    'settings.sessions.awayRecap.help' => 'Quando o terminal reporta o regresso do foco após três minutos ou mais de ausência, imprime um resumo de onde a sessão ficou (uma chamada ao modelo de título por ausência); desativado deixa o regresso silencioso. `/recap` pede um a qualquer momento.',
    'settings.skills.listingMaxBytes.help' => 'Orçamento em bytes para toda a listagem de competências no prompt do sistema; competências além disso colapsam numa linha "N more skills".',
    'settings.skills.pathNudges.help' => 'Quando uma ferramenta toca num ficheiro coberto por uma competência com âmbito de caminho, lembra ao modelo que essa competência existe, uma vez por competência.',
    'settings.statusLine.help' => '{"type": "command", "command": "…", "refreshSeconds": 2}: um comando de shell cuja saída preenche a barra de estado, reexecutado a cada refreshSeconds (2 a 3600, predefinição: 2). Recebe a sessão como um documento JSON em stdin (session_id, cwd, model, workspace, version, cost, mais extras de candy_code); um comando que nunca lê stdin é executado na mesma.',
    'settings.streamHeaderTimeoutSeconds.help' => 'Segundos que um servidor de streaming ligado pode demorar a enviar os cabeçalhos de resposta; nunca um tempo limite total do pedido.',
    'settings.streamIdleTimeoutSeconds.help' => 'Segundos que uma leitura de uma resposta em streaming pode esperar por bytes antes de a ligação ser considerada morta; por leitura, nunca um total.',
    'settings.subagentMaxActive.help' => 'Execuções delegadas que uma sessão pode ter em curso simultaneamente, contando cada nível, membro e agente em segundo plano; além disso, uma chamada `Task` é recusada. Não definido — a predefinição — ou 0 não impõe limite.',
    'settings.subagentMaxConcurrent.help' => 'Chamadas `Task` de um lote que executam em simultâneo (as restantes aguardam uma posição livre), e a largura de cada pool de agentes. Não definido — a predefinição — ou 0 não impõe limite.',
    'settings.subagentMaxDepth.help' => 'Níveis abaixo da sessão em que uma execução delegada pode estar; uma execução no último nível não recebe `Task`. 1 impede que sub-agentes deleguem mais.',
    'settings.subagentMaxTurns.help' => 'Limite de passos para um sub-agente — uma delegação `Task`, uma etapa de fluxo de trabalho ou uma execução `executeAgents` — cuja predefinição não declara `maxTurns`.',
    'settings.subagentModel.help' => 'Modelo em que um sub-agente delegado corre quando a sua predefinição diz `inherit`; não definido segue o modelo da sessão.',
    'settings.summaryModel.help' => 'Modelo que escreve resumos de compactação; não definido usa o próprio modelo da conversa, que reutiliza a cache de prompts.',
    'settings.symbolMap.enabled.help' => 'Inserir o mapa de símbolos do repositório classificado por nível no prompt de sistema, capturado uma vez por sessão.',
    'settings.temperature.help' => 'Temperatura de amostragem que o fornecedor `custom` envia quando um pedido não nomeia nenhuma.',
    'settings.terminalBackground.help' => 'O que o tema adaptativo assume por trás do texto: auto pergunta ao terminal (OSC 11, depois COLORFGBG); light ou dark afirmam-no diretamente.',
    'settings.testCommand.help' => 'Comando de shell que executa os testes do projeto, na raiz do projeto (`composer test`, `pytest -q`); o que `autoTest` executa.',
    'settings.theme.help' => 'Tema de cores; /theme e a paleta alteram-no em tempo real. Temas personalizados carregam de ficheiros JSON sob ~/.candy-code/themes.',
    'settings.thinkingBudget.help' => 'Orçamento de tokens de raciocínio: `thinkingConfig` do Gemini no fornecedor `vertex`; raciocínio estendido no fornecedor `anthropic`, onde o mínimo da Messages API é 1024 (0 ou não definido significa desligado em qualquer ramo). Tokens de raciocínio são faturados como saída.',
    'settings.titleModel.help' => 'Modelo que nomeia sessões e escreve sugestões de prompt; não definido usa o padrão auxiliar barato do tipo de fornecedor antes do modelo de bloco.',
    'settings.transcriptJsonl.help' => 'Espelhar cada transcrição confirmada num diário JSONL só de acréscimo sob `~/.candy-code/transcripts/<project>/` (ficheiros 0600), e fornecer aos scripts de hook uma chave de stdin `transcript_path` que aponta para ele. O diário contém a conversa bruta e cresce sem limite; lido no arranque, pelo que uma alteração se aplica no próximo início.',
    'settings.toolInstructionCapBytes.help' => 'Máximo de bytes do corpo de um CLAUDE.md/AGENTS.md de controlo que um resultado Edit, Write ou ApplyPatch pode transportar; o restante é cortado com um marcador.',
    'settings.toolOutputCapBytes.help' => 'Máximo de bytes que um resultado Bash, Grep, Glob, Lsp ou WebFetch pode entregar ao modelo; o que é cortado é guardado num ficheiro que o resultado nomeia.',
    'settings.toolOutputPreviewLines.help' => 'Linhas de um resultado de ferramenta colapsado mostradas na transcrição; Ctrl+O expande o resto.',
    'settings.toolSpillCaptureBytes.help' => 'Máximo da saída de um comando Bash (por fluxo) mantido em memória e guardado no ficheiro de transbordo quando o resultado é cortado; nunca abaixo do limite de saída.',
    'settings.toolSpillMinCapBytes.help' => 'Menor limite de resultado a partir do qual um resultado de ferramenta cortado é guardado num ficheiro; abaixo dele, o corte é anunciado e o resto descartado.',
    'settings.toolSpillWindowPercent.help' => 'Maior fração da janela de contexto que um resultado de ferramenta pode ocupar; além dela, o resultado é guardado num ficheiro e ao modelo é mostrado o início e o fim.',
    'settings.trustedProjectCommands.help' => 'Raízes de projeto cujos comandos de barra podem executar blocos de shell !`cmd`.',
    'settings.trustedBundleCommands.label' => 'Comandos de pacote confiáveis',
    'settings.trustedBundleCommands.help' => 'Nomes de pacotes de plugin cujos ficheiros de comandos podem executar blocos de shell !`cmd`; cada comando continua a ser julgado pelo portão de permissões. Os nomes correspondem ao nome do manifesto do próprio pacote, e apenas instalações a nível de utilizador contam — uma checkout de projeto não pode conceder shell a si mesma, nem sequer usurpando um nome listado. Optar não é um contorno: no portão apenas uma regra Deny recusa, e uma regra que o portão avalia como Ask executa sem supervisão — a expansão não tem prompt para mostrar. Vazio por omissão, pelo que os comandos de pacote não executam shell.',
    'settings.mcpPromptShell.label' => 'Shell de prompt MCP',
    'settings.mcpPromptShell.help' => 'Chaves de servidores MCP cujos corpos de prompt podem executar blocos de shell !`cmd`; cada comando continua a ser julgado pelo portão de permissões. Os nomes correspondem à chave que a sua configuração de utilizador dá ao servidor. Apenas nível de utilizador; vazio por omissão, pelo que os prompts obtidos não executam shell. Optar não é um contorno: no portão apenas uma regra Deny recusa, e uma regra que o portão avalia como Ask executa sem supervisão — a expansão não tem prompt para mostrar.',
    'settings.trustedProjectHooks.help' => 'Raízes de projeto cujos .candy-code/hooks.yaml podem executar.',
    'settings.trustedProjectMcp.help' => 'Raízes de projeto cujos servidores .mcp.json podem ser iniciados.',
    'settings.trustedProjectSettings.help' => 'Raízes de projeto cujos .candy-code/settings*.json podem definir as chaves de nível de projeto.',
    'settings.turnIdleTimeoutSeconds.help' => 'Segundos que um turno em execução pode passar sem qualquer progresso antes de ser interrompido como pendurado; tempo de inatividade, nunca um total.',
    'settings.ui.imageRenderMode.help' => 'Como as imagens geradas são pintadas no terminal; `auto` escolhe o melhor protocolo que o terminal reporta.',
    'settings.ui.mediaDisplayOverrides.help' => 'Ajustes de visualização por modo de renderização (limites de tamanho, soluções de recurso); as chaves são os nomes dos modos de renderização, os valores os parâmetros de visualização.',
    'settings.vimMode.help' => 'Edição NORMAL/INSERT na caixa de rascunho (i a I A o O Esc, h j k l w b e 0 $ x, dd D cc C yy y p P v V, objetos de texto di" da( ciw, contagens 3dd d2w): movimentos, alteração, eliminação e yank em NORMAL, digitação literal em INSERT. Um modo, não atalhos — nunca aparece em /keys. Aplica-se no próximo toque de tecla após guardar.',
    'settings.voice.apiKey.help' => 'Chave Bearer enviada ao endpoint de transcrição, se este exigir uma; prefira a forma de placeholder `${VAR}` em vez de um literal.',
    'settings.voice.baseUrl.help' => 'URL base HTTP de um endpoint de transcrição compatível com OpenAI (um `/v1` final é mantido); a gravação é enviada apenas para lá e para mais lado nenhum. Sem predefinição: a entrada por voz permanece OFF até isto ser definido no nível de utilizador.',
    'settings.voice.language.help' => 'Código BCP-47 (`en`, `de`) que força a língua da transcrição; não definido deixa o endpoint detetá-la.',
    'settings.voice.maxSeconds.help' => 'Limite rígido em segundos de uma gravação (5-600, predefinição 120). O limite acompanha o argumento do gravador, pelo que uma gravação órfã se interrompe sozinha.',
    'settings.voice.model.help' => 'Id do modelo enviado com cada pedido de transcrição; `whisper-1` responde em endpoints compatíveis com OpenAI.',
    'settings.watchFiles.help' => 'Enviar um prompt quando um ficheiro guardado contém um comentário terminado em AI! (fazer uma alteração) ou AI? (responder a uma pergunta); comentários AI simples acompanham como contexto. Sondado enquanto o chat está inativo; apenas comentários guardados após o arranque são acionados, cada um uma vez. Apenas sessões de terminal: o monitor corre no processo do terminal, pelo que uma sessão alojada por `candy-code serve` não monitoriza ficheiros.',
    'settings.webFetchMaxBytes.help' => 'Máximo do corpo obtido mantido em memória; um limite de memória, o limite de saída é o que chega ao modelo.',
    'settings.webFetchTimeoutSeconds.help' => 'Segundos que uma leitura de socket do WebFetch pode bloquear antes de a obtenção falhar.',
    'settings.webSearchBackend.help' => 'Que serviço de pesquisa o WebSearch consulta: `searxng` (a predefinição) envia cada consulta ao `webSearchEndpoint` configurado; `brave`, `tavily` e `exa` ligam ao host fixo desse serviço em vez disso e cada um precisa da sua chave de API no ambiente (`BRAVE_SEARCH_API_KEY`, `TAVILY_API_KEY`, `EXA_API_KEY`), sem forma de os apontar para outro URL.',
    'settings.webSearchEndpoint.help' => 'URL de pesquisa de uma instância SearXNG em que confia (`https://searx.example.org/search`); cada consulta WebSearch é enviada para lá.',
    'settings.webSearchMaxResults.help' => 'Resultados que um resumo do WebSearch lista, cada um com título, URL e fragmento.',
    'settings.webSearchTimeoutSeconds.help' => 'Segundos que um pedido de pesquisa pode demorar.',
    'settings.webhooks.help' => 'Mapa de nome de hook para {secret, prompt, permissionMode?, rate?}; POST /api/hooks/{name} insere então o corpo (escapado como não confiável) no prompt e inicia uma sessão em segundo plano. Vazio (predefinição) não monta nada. rate é N entregas por minuto por endereço, e por hook no total. bypass-permissions é recusado para hooks no arranque; um hook sem modo corre no mais restritivo entre o modo do servidor e a predefinição. Uma linha pode também nomear signature: {scheme: "github-sha256"|"hmac-sha256", header?, deliveryHeader?}: a rota verifica então um HMAC-SHA256 do corpo bruto (sha256=<hex>) com o segredo da linha através do cabeçalho de assinatura, em vez do segredo de cabeçalho personalizado, porque o GitHub não pode enviar cabeçalhos personalizados; assinaturas falhadas alimentam o mesmo bloqueio por hook, e um id de entrega já visto (X-GitHub-Delivery por predefinição para o esquema GitHub; o deliveryHeader configurado para um genérico) responde {"ok": true, "duplicate": true} sem iniciar uma segunda sessão.',
    'settings.webhooksOut.help' => 'Mapa de nome de endpoint para {url, secret, events}; events é uma lista não vazia extraída de turn.completed, session.ended, permission.asked e schedule.fired. Vazio (predefinição) não abre qualquer egresso. Lido apenas no nível USER — uma configuração de projeto ou bundle nunca pode adicionar um endpoint de saída. url deve ser https, ou http apenas quando o seu host literal é localhost ou um endereço de loopback, e nunca transporta userinfo; secret tem pelo menos 16 caracteres e assina cada entrega com HMAC-SHA256 como X-Candy-Code-Signature (sha256=<hex> sobre o corpo exato) emparelhado com X-Candy-Code-Timestamp. A entrega é assíncrona no event loop — os despachos nunca aguardam resposta: um limite de conexão de 2 segundos e um teto de rede de 10 segundos por POST delimitam cada entrega (limites de webhook, não um timeout de pedido LLM), transportes falhados e respostas 5xx seguem uma escada de tentativas de 2/8/30 segundos, respostas 4xx e de redirecionamento são definitivas à primeira porque redirecionamentos são recusados em vez de seguidos, e uma fila limitada de 128 entregas em curso descarta novos despachos em caso de overflow em vez de aumentar a memória. Lido no arranque; alterar o mapa tem efeito no reinício.',
    'settings.webhooksOut.refuse' => 'webhooksOut na configuração do utilizador é inutilizável: {reason}. Recuso iniciar em vez de entregar a um endpoint parcialmente verificado — corrija o mapeamento ou remova a chave para executar sem webhooks de saída.',
    // --- end settings help ---

    // --- begin tui.window (P-TABS.a) ---
    // Strings of the window-strip kit in src/Tui/Window/. Census law
    // (TuiLangTest): every key here must ride as a single-quoted literal
    // under src/Tui/ or src/Palette/, and every such literal must exist
    // here. The kit quotes exactly these four.
    'tui.window.overflow' => '‹{count}›',
    'tui.window.unnamed' => 'janela',
    'tui.window.summary' => '{sessions} janelas · {attention} precisam de atenção',
    'tui.window.summary.none' => 'sem janelas abertas',
    // --- end tui.window (P-TABS.a) ---

    // --- begin tui.window.title (P-TABS.g) ---
    // OSC 2 window title and background-tab notices, named from
    // src/App/App.php's deck choke (windowList/afterDeckChange).
    'tui.window.title.plain' => 'candy-code',
    'tui.window.title.attention' => 'candy-code — {waiting} em espera · {running} em execução',
    'tui.window.attention.waiting' => '{name} aguarda uma resposta',
    'tui.window.attention.unseen' => '{name} terminou enquanto esteve ausente',
    // --- end tui.window.title (P-TABS.g) ---

    // --- begin tui.sessions (P-TABS.c) ---
    // Strings of the vertical sessions pane in
    // src/Tui/Components/SessionsPane.php. Same census law as the block
    // above (TuiLangTest): quoted keys ride the source, source literals
    // live here.
    'tui.sessions.new' => '＋ Nova sessão',
    'tui.sessions.title' => 'Sessões',
    'tui.sessions.unnamed' => 'sessão',
    'tui.sessions.agents' => '{count} agentes',
    // --- end tui.sessions (P-TABS.c) ---

    // --- session.import (C-SES-7.a: the importer core) ---
    'session.import.notice' => 'Transcrição {format} importada — material de referência não confiável: a atividade das ferramentas é registada como texto, nunca reproduzida.',
    'session.import.refusal.not_readable' => 'import: {path} não é um ficheiro legível, pelo que nada foi importado',
    'session.import.refusal.source_shrank' => 'import: a origem contém agora menos linhas de transcrição do que as armazenadas pela última importação, e uma transcrição reduzida é recusada em vez de reescrita',
    'session.import.refusal.too_large' => 'import: a transcrição tem {bytes} bytes, acima do limite de {max} bytes',
    'session.import.refusal.too_many_items' => 'import: a transcrição contém mais linhas do que o limite de {max} linhas',
    'session.import.refusal.unknown_format' => 'import: o ficheiro não corresponde a uma transcrição de CandyCode, Claude Code, Codex ou OpenCode, pelo que nada foi inferido',
    'session.import.refusal.unsupported_shape' => 'import: a forma da transcrição não é reconhecida ({detail}); formatos desconhecidos são recusados, nunca adivinhados',
    // --- end session.import ---

    // --- begin tui.diffreview (C-TUI-2.d: diff-review core) ---
    'tui.diffreview.title' => 'Ficheiros alterados {steps} ponto(s) de controlo atrás',
    'tui.diffreview.turn_suffix' => ' · só neste turno',
    'tui.diffreview.empty' => '(nada alterado desde esse ponto de verificação)',
    'tui.diffreview.omitted' => '… {lines} linhas omitidas no limite de visualização',
    'tui.diffreview.hints' => '↑/↓ ficheiro · PgUp/PgDn corpo · -/+ base · t este turno · Esc fechar',
    // --- end tui.diffreview (C-TUI-2.d) ---
    // --- begin commit (C-AGT-6.a: /commit builtin) ---
    // Strings of the manual whole-tree commit: src/Host/Commands/
    // CommitHostCommand.php and builtin-commands/2850-commit.php. The drafting
    // itself rides CommitMessageWriter, shared with the `turn`-mode auto-commit.
    'cmd.commit.description' => 'Confirmar todos os ficheiros alterados, redigindo a mensagem quando não fornecer nenhuma',
    'cmd.commit.hint' => '<message>',
    'host.commit.nothing' => 'Nada para submeter: a árvore de trabalho está limpa.',
