    // outside --bare (probe: claude --help, 2.1.312).
    'provider.claude_code.isolation_notice' => 'claude-code `bare: false`: o processo filho da CLI está isolado nas fontes de definições de projeto/locais, na sua própria configuração MCP e sem slash-commands nem skills — mas a auto-descoberta de CLAUDE.md e a auto-memória continuam a carregar; apenas `bare: true` as ignora, e `isolate: false` restaura o estado completo do utilizador.',
